values
  ('math-board-mymensingh-2023-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', '2ab এর মান নিচের কোনটি?', 'mcq', '{"ক":"2","খ":"8","গ":"32","ঘ":"128"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, 'a+b = √10 এবং a−b = √6', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', '1/2(a²+b²) এর মান কত?', 'mcq', '{"ক":"16","খ":"8","গ":"4","ঘ":"2"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, 'a+b = √10 এবং a−b = √6', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', 'A = {x: x, 6 এর গুণনীয়কসমূহ} এবং B = {x: x 3 এর গুণিতক এবং x≤6}, হলে A−B নিচের কোনটি?', 'mcq', '{"ক":"{1,2}","খ":"{3,4}","গ":"{1,3}","ঘ":"{1,2,3,6}"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', 'sinθ + cosθ = 1 হলে 3 sinθ·cosθ = ?', 'mcq', '{"ক":"","খ":"1/3","গ":"1/2","ঘ":"1"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ক অপশন ছাপায় অনুপস্থিত; ক-র মান ছাপায় নেই বলে অপশন খালি রাখা হলো — গণনা করে বসানো হয়নি। ছাপা চাবি ক।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', '3 সে.মি. ব্যাসার্ধবিশিষ্ট বৃত্তের কেন্দ্র থেকে 2 সে.মি. দূরবর্তী জ্যা এর দৈর্ঘ্য কত?', 'mcq', '{"ক":"10 সে.মি.","খ":"2/5 সে.মি.","গ":"5 সে.মি.","ঘ":"2√5 সে.মি."}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', '3 সে.মি. এবং 2 সে.মি. ব্যাসার্ধবিশিষ্ট এক কেন্দ্রিক দুইটি বৃত্তক্ষেত্রের পরিবেষ্টনের মাঝের অংশের ক্ষেত্রফল কত বর্গ সে.মি.?', 'mcq', '{"ক":"5π","খ":"4π","গ":"3π","ঘ":"π"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'p+q+r = 6 এবং p²+q²+r² = 14 হলে (pq+qr+rp) এর মান কত?', 'mcq', '{"ক":"50","খ":"25","গ":"22","ঘ":"11"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'কোনো সমতলে— i. দুইটি নির্দিষ্ট বিন্দু দিয়ে অসংখ্য বৃত্ত আঁকা যায়। ii. সমরেখ নয় এমন তিনটি বিন্দু দিয়ে কেবল ১টি বৃত্ত আঁকা যায়। iii. বৃত্তের ব্যাস অন্য যে কোনো জ্যা অপেক্ষা বৃহত্তর কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'একজন বোলার দুই ওভার বল করে যথাক্রমে 2, 6, 1, 6, 3, 0, 4, 6, 0, 3, 2, 1 রান দেন। বোলারের দেওয়া রানের প্রচুরক কত?', 'mcq', '{"ক":"3.5","খ":"6","গ":"17","ঘ":"34"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ছাপায় রানের তালিকায় ''03'' (0 ও 3-এর মাঝে কমা অনুপস্থিত); 2, 6, 1, 6, 3, 0, 4, 6, 0, 3, 2, 1 ধরে লেখা হয়েছে।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'f(x) = (2x+1)/(2x−1) হলে f(−1/2) এর মান কোনটি?', 'mcq', '{"ক":"2","খ":"−1","গ":"","ঘ":"1"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'গ অপশন ছাপায় অনুপস্থিত; গ-র মান ছাপায় নেই বলে অপশন খালি রাখা হলো — গণনা করে বসানো হয়নি। ছাপা চাবি গ।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'OE = OF হলে CD = কত?', 'mcq', '{"ক":"4 সে.মি.","খ":"6 সে.মি.","গ":"8 সে.মি.","ঘ":"10 সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'চিত্র: O কেন্দ্রবিশিষ্ট বৃত্তে AB ও CD দুটি জ্যা, OE ⊥ AB, OF ⊥ CD, BE = 4 সে.মি.।', 'উদ্দীপকের আলোকে নিচের প্রশ্ন দুটির উত্তর দাও: চিত্রে O বৃত্তের কেন্দ্র এবং BE = 4 সে.মি.', 'mymensingh', 2023, 'diagram'),
  ('math-board-mymensingh-2023-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', '3.5 সে.মি. ব্যাসার্ধবিশিষ্ট বৃত্তের কেন্দ্রগামী জ্যা এর দৈর্ঘ্য কত?', 'mcq', '{"ক":"3.5 সে.মি.","খ":"4.5 সে.মি.","গ":"7 সে.মি.","ঘ":"14 সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, 'উদ্দীপকের আলোকে নিচের প্রশ্ন দুটির উত্তর দাও: চিত্রে O বৃত্তের কেন্দ্র এবং BE = 4 সে.মি.', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'নিচের কোনটি বিচ্ছিন্ন চলক?', 'mcq', '{"ক":"উচ্চতা","খ":"তাপমাত্রা","গ":"জনসংখ্যা","ঘ":"বয়স"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p33', 'একটি বর্গের অন্তর্বৃত্তের ব্যাসার্ধ 3.2 সে.মি. হলে বর্গের পরিসীমা কত সে.মি.?', 'mcq', '{"ক":"25.6","খ":"19.2","গ":"12.8","ঘ":"6.4"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'একটি সুষম অষ্টভুজের একটি শীর্ষকোণের মান কত?', 'mcq', '{"ক":"45°","খ":"135°","গ":"120°","ঘ":"180°"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'কোনো সমবাহু ত্রিভুজের উচ্চতা 2√3 সে.মি. হলে এর বাহুর দৈর্ঘ্য কত সে.মি.?', 'mcq', '{"ক":"√3","খ":"2","গ":"2√3","ঘ":"4"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'sin3A = cos3A হলে tan4A = কত?', 'mcq', '{"ক":"√3","খ":"1","গ":"2√3","ঘ":"2"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'উপাত্তের মধ্যক কোনটি?', 'mcq', '{"ক":"16","খ":"55","গ":"50","ঘ":"65"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'সারণি অনুযায়ী n = 50, 25তম/26তম মান 60 (ঘ); ছাপা চাবি c (50) গাণিতিকভাবে মেলে না — অডিটে নিষ্পত্তি আবশ্যক।', 'ওজন (কেজি): 45, 50, 55, 60, 65, 70; গণসংখ্যা: 2, 6, 8, 16, 12, 6।', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'কোনো গণসংখ্যা নিবেশনের আনুমানিক গড় 16, বিচ্যুতির গড় 1 এবং শ্রেণি ব্যবধান 4 হলে, গাণিতিক গড় কত?', 'mcq', '{"ক":"24","খ":"20","গ":"16","ঘ":"12"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'X = {−1, 0, 1, 2} এর প্রকৃত উপসেট সংখ্যা কত?', 'mcq', '{"ক":"16","খ":"15","গ":"8","ঘ":"4"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'ধারাটির সাধারণ অন্তর কত?', 'mcq', '{"ক":"−8","খ":"−2","গ":"2","ঘ":"24"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, 'তথ্যের আলোকে নিচের প্রশ্ন দুটির উত্তর দাও: সমান্তর ধারার প্রথম পদ 24 এবং 10তম পদ 6', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', 'ধারাটির ১ম ১০টি পদের সমষ্টি কত?', 'mcq', '{"ক":"330","খ":"150","গ":"120","ঘ":""}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ঘ অপশন ছাপায় অনুপস্থিত।', 'তথ্যের আলোকে নিচের প্রশ্ন দুটির উত্তর দাও: সমান্তর ধারার প্রথম পদ 24 এবং 10তম পদ 6', 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', '0.00234 এর লগের অংশক কত?', 'mcq', '{"ক":"−2.6308","খ":"−2","গ":"0.3692","ঘ":"0.6308"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p34', '3^(x−2) = 2178 হলে x এর মান কত?', 'mcq', '{"ক":"−9","খ":"−5","গ":"5","ঘ":"9"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ছাপায় 2178; 3^7 = 2187 হলে x = 9 (ঘ) মেলে — 2178-এ 7/8 অদলবদল থাকতে পারে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p35', 'কোনো বৃত্তের i. অধিচাপে অন্তর্লিখিত কোণ সূক্ষ্মকোণ ii. উপচাপে অন্তর্লিখিত কোণ স্থূলকোণ iii. অন্তর্লিখিত সামান্তরিক একটি আয়ত কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ছাপায় ii-কে ''i.'' লেখা (দ্বিতীয় বিবৃতির লেবেল ভুল); ii ধরে লেখা হয়েছে।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p35', '△ABC এ ∠A = ∠B+∠C হলে ∠A এর মান কত?', 'mcq', '{"ক":"30°","খ":"60°","গ":"45°","ঘ":"90°"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p35', 'একটি ত্রিভুজ আঁকার জন্য প্রয়োজন— i. দুইটি বাহু ও এদের অন্তর্ভুক্ত কোণ ii. তিনটি বাহু iii. দুইটি কোণ ও কোণ সংলগ্ন ১টি বাহু নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p35', 'AB = CD এবং OF = 3 সে.মি. হলে বৃত্তটির ব্যাস কত সে.মি.?', 'mcq', '{"ক":"3","খ":"4","গ":"5","ঘ":"10"}'::jsonb, 'ঘ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'Q11-এর চিত্রের উপর নির্ভরশীল; চিত্র: O কেন্দ্রবিশিষ্ট বৃত্তে AB ও CD দুটি জ্যা, OE ⊥ AB, OF ⊥ CD, BE = 4 সে.মি. — AB = 8, AB = CD, OF = 3 হলে ব্যাসার্ধ 5, ব্যাস 10। ব্যাখ্যাটি হাতে-লেখা ছবি; প্রথম লাইনের = চিহ্নগুলো হালকা ছাপা (300 dpi-তে পড়া হয়েছে)।', 'চিত্রে O বৃত্তের কেন্দ্র এবং BE = 4 সে.মি.', 'mymensingh', 2023, 'diagram'),
  ('math-board-mymensingh-2023-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p36', 'cot(A+30°) = 0 হলে sinA = কত?', 'mcq', '{"ক":"√3/2","খ":"1/√2","গ":"1/2","ঘ":""}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', 'ঘ অপশন ছাপায় অনুপস্থিত।', null, 'mymensingh', 2023, null),
  ('math-board-mymensingh-2023-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p36', 'secθ + tanθ = 2/7 হলে secθ = কত?', 'mcq', '{"ক":"45/28","খ":"53/28","গ":"45/14","ঘ":"53/14"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2023-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2023, null),
