  ('math-board-barishal-2023-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'দুইটি বৃত্ত পরস্পরকে ছেদ করলে তাদের মধ্যে সর্বোচ্চ কয়টি সাধারণ স্পর্শক অঙ্কন করা সম্ভব?', 'mcq', '{"ক":"1টি","খ":"2টি","গ":"3টি","ঘ":"4টি"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'কোনো বৃত্তের অধিচাপে অন্তর্লিখিত কোণ—', 'mcq', '{"ক":"সমকোণ","খ":"স্থূলকোণ","গ":"সূক্ষ্মকোণ","ঘ":"প্রবৃদ্ধ কোণ"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'একটি রম্বসের দুইটি কর্ণের দৈর্ঘ্য 8 একক ও 12 একক হলে এর ক্ষেত্রফল কত বর্গ একক?', 'mcq', '{"ক":"40","খ":"48","গ":"96","ঘ":"192"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'সমবৃত্তভূমিক বেলনের ভূমির ব্যাসার্ধ 5 সে.মি. এবং উচ্চতা 7 সে.মি. হলে এর— i. ভূমির ক্ষেত্রফল = 25π বর্গ সে.মি. ii. বক্রতলের ক্ষেত্রফল 70π বর্গ সে.মি. iii. আয়তন = 350π ঘন সে.মি. নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', 'ii-তে ছাপায় ''৭০π'' অস্পষ্টভাবে ''(ঘ) 0π''-এর মতো দেখায়; 2πrh = 70π অনুযায়ী লেখা হয়েছে। iii ভুল (আয়তন 175π), তাই চাবি a (i ও ii) সঠিক।', null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'x sinθ = y হলে cotθ এর মান কোনটি?', 'mcq', '{"ক":"√(x²−y²)/x","খ":"√(x²−y²)/y","গ":"x/√(x²−y²)","ঘ":"y/√(x²−y²)"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p38', 'অজিভ রেখা অঙ্কনের ক্ষেত্রে x-অক্ষ বরাবর স্থাপন করা হয়—', 'mcq', '{"ক":"শ্রেণির উচ্চমান","খ":"শ্রেণির নিম্নমান","গ":"শ্রেণির মধ্যমান","ঘ":"অবিচ্ছিন্ন শ্রেণি ব্যাপ্তি"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', 'যদি f(x) = x³ − 5x + 2 হলে f(−2) = কত?', 'mcq', '{"ক":"−16","খ":"−14","গ":"6","ঘ":"4"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', 'P = {a, b, c}, Q = {b, d} হলে (P\Q) এর প্রকৃত উপসেট কয়টি?', 'mcq', '{"ক":"2","খ":"3","গ":"4","ঘ":"7"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', '8 সে.মি. ও 6 সে.মি. ব্যাসবিশিষ্ট দুইটি বৃত্ত পরস্পরকে বহিঃস্পর্শ করলে তাদের কেন্দ্রদ্বয়ের মধ্যবর্তী দূরত্ব নিচের কোনটি?', 'mcq', '{"ক":"1 সে.মি.","খ":"2 সে.মি.","গ":"7 সে.মি.","ঘ":"14 সে.মি."}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', 'ব্যাস 8 ও 6 হলে কেন্দ্রদ্বয়ের দূরত্ব 4+3 = 7 (গ) হওয়ার কথা; ছাপা চাবি d (14) — সংখ্যা দুটি ব্যাসার্ধ হিসেবে ধরা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', '△ABC এর পরিকেন্দ্র O, AB = AC এবং ∠ABC = 55° হলে ∠BOC = কত?', 'mcq', '{"ক":"140°","খ":"125°","গ":"110°","ঘ":"70°"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', 'y + 1/y = 5 হলে y/(y²−3y+1) = কত?', 'mcq', '{"ক":"1/8","খ":"1/2","গ":"2","ঘ":"8"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', null, null, 'barishal', 2023, null),
  ('math-board-barishal-2023-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', 'cos(90° − B) = কত?', 'mcq', '{"ক":"1/2","খ":"1/√2","গ":"1/√3","ঘ":"√3/2"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', 'চিত্র: O মূলবিন্দু, OB ডানে (OB = 1), OQ বামে, OA উপরে (OA = √3), O-তে সমকোণ; AB-কে A ছাড়িয়ে P পর্যন্ত বর্ধিত (B = 60°)।', 'চিত্রের আলোকে নিচের প্রশ্নের উত্তর দাও:', 'barishal', 2023, 'diagram'),
  ('math-board-barishal-2023-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p39', 'চিত্রে— i. cosec(A+B) = 1 ii. sinA + cosB = 1 iii. tan∠AOQ অসংজ্ঞায়িত নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2023-mcq', false, null, 'board-mcq', 'চিত্র: O মূলবিন্দু, OB ডানে (OB = 1), OQ বামে, OA উপরে (OA = √3), O-তে সমকোণ; AB-কে A ছাড়িয়ে P পর্যন্ত বর্ধিত।', 'চিত্রের আলোকে নিচের প্রশ্নের উত্তর দাও:', 'barishal', 2023, 'diagram'),
