  ('math-board-dinajpur-2023-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p40', 'প্রচুরক শ্রেণির পূর্বের শ্রেণির ক্রমযোজিত গণসংখ্যা কত?', 'mcq', '{"ক":"31","খ":"18","গ":"13","ঘ":"8"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2023-mcq', false, null, 'board-mcq', null, 'শ্রেণি ব্যবধান: 31-35, 36-40, 41-45, 46-50, 51-55, 56-60; গণসংখ্যা: 5, 8, 18, 15, 12, 10।', 'dinajpur', 2023, null),
  ('math-board-dinajpur-2023-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p40', '−5 থেকে 5 পর্যন্ত পূর্ণ সংখ্যাগুলোর মধ্যক কত?', 'mcq', '{"ক":"−5","খ":"−1","গ":"","ঘ":"5"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2023-mcq', false, null, 'board-mcq', 'গ অপশন ছাপায় অনুপস্থিত; গ-র মান ছাপায় নেই বলে অপশন খালি রাখা হলো — গণনা করে বসানো হয়নি। ছাপা চাবি গ।', null, 'dinajpur', 2023, null),
