  ('math-board-cumilla-2023-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p44', 'log_x 27 = −3 হলে x এর মান কত?', 'mcq', '{"ক":"−9","খ":"−3","গ":"−1/3","ঘ":"1/3"}'::jsonb, 'ঘ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
