  ('math-board-cumilla-2023-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p44', 'প্রথম দশটি স্বাভাবিক সংখ্যার বর্গের সমষ্টি কত?', 'mcq', '{"ক":"55","খ":"110","গ":"385","ঘ":"3025"}'::jsonb, 'গ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'একটি সামান্তরিকের ভূমি 12 সে.মি. এবং উচ্চতা 12 সে.মি. হলে ক্ষেত্রফল কত?', 'mcq', '{"ক":"24 বর্গ সে.মি.","খ":"72 বর্গ সে.মি.","গ":"144 বর্গ সে.মি.","ঘ":"288 বর্গ সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'একটি আয়তের বাহু দুটি যথাক্রমে 12 সে.মি. ও 5 সে.মি. হলে এর কর্ণদ্বয়ের সমষ্টি কত?', 'mcq', '{"ক":"13 সে.মি.","খ":"17 সে.মি.","গ":"26 সে.মি.","ঘ":"60 সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'রম্বসের দুটি কর্ণ 8 সে.মি. ও 6 সে.মি. হলে এর ক্ষেত্রফল কত বর্গ সে.মি.?', 'mcq', '{"ক":"24","খ":"48","গ":"100","ঘ":"196"}'::jsonb, 'ক', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', 'প্রথম কর্ণের অঙ্কটি ছাপায় অস্পষ্ট (৪/৮-এর মতো দেখায়); ক্ষেত্রফল 24 (চাবি ক) থেকে কর্ণ 8 সে.মি. নিশ্চিত — (1/2)×8×6 = 24।', null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'একটি ত্রিভুজের তিনটি বাহু 5 সে.মি., 6 সে.মি. ও 7 সে.মি. হলে—
