  ('math-board-cumilla-2023-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'একটি সুষম ষড়ভুজের ক্ষেত্রফল 18√3 বর্গ একক হলে এর বাহুর দৈর্ঘ্য কত একক?', 'mcq', '{"ক":"3","খ":"2√3","গ":"6","ঘ":"9"}'::jsonb, 'খ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'cos2A = 0 হলে, tan2A এর মান কত?', 'mcq', '{"ক":"","খ":"1","গ":"√3","ঘ":"অসংজ্ঞায়িত"}'::jsonb, 'ঘ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', 'ছাপায় ক অপশন অনুপস্থিত (শুধু খ, গ, ঘ ছাপা); ক-র মান ছাপায় নেই বলে অপশন খালি রাখা হলো — গণনা করে বসানো হয়নি। ছাপা চাবি ঘ; cos2A = 0 হলে 2A = 90°, tan2A অসংজ্ঞায়িত।', null, 'cumilla', 2023, null),
  ('math-board-cumilla-2023-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p45', 'A − B = 30° এবং cotA = 1 হলে B এর মান কত?', 'mcq', '{"ক":"0°","খ":"15°","গ":"30°","ঘ":"45°"}'::jsonb, 'খ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
