  ('math-board-cumilla-2023-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p46', 'P = {2, 4, 6} এবং Q = {3, 6, 7} হলে P − Q নিচের কোনটি?', 'mcq', '{"ক":"{2, 3, 4, 6, 7}","খ":"{2, 3, 6, 7}","গ":"{2, 4, 6}","ঘ":"{2, 4}"}'::jsonb, 'ঘ', null, 1, false, 'math-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
