  ('math-board-jessore-2023-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p46', 'tanθ = 4/5 হলে cosecθ/cotθ = কত?', 'mcq', '{"ক":"√41/4","খ":"√41/5","গ":"5/√41","ঘ":"4/√41"}'::jsonb, 'খ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, null, 'jessore', 2023, null),
