  ('math-board-jessore-2023-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', '0.0000625 এর বৈজ্ঞানিক রূপ নিচের কোনটি?', 'mcq', '{"ক":"6.25×10⁵","খ":"6.25×10⁴","গ":"6.25×10⁻⁴","ঘ":"6.25×10⁻⁵"}'::jsonb, 'ঘ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, null, 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'ধারাটির পদসংখ্যা কত?', 'mcq', '{"ক":"13","খ":"12","গ":"11","ঘ":"10"}'::jsonb, 'খ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', 'উদ্দীপকে বোর্ডের মূল নম্বর (২০ ও ২১ নং) ছাপা; এই সেটে প্রশ্ন নং ১৯ ও ২০।', '25 + 21 + 17 +..........−19 ধারাটি থেকে ২০ ও ২১ নং প্রশ্নের উত্তর দাও:', 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'ধারাটির প্রথম দশ পদের সমষ্টি কত?', 'mcq', '{"ক":"70","খ":"140","গ":"305","ঘ":"430"}'::jsonb, 'ক', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, '25 + 21 + 17 +..........−19 ধারাটি থেকে ২০ ও ২১ নং প্রশ্নের উত্তর দাও:', 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'উপচাপের অনুবন্ধী চাপে অন্তর্লিখিত কোণ কোন ধরনের কোণ?', 'mcq', '{"ক":"সূক্ষ্মকোণ","খ":"স্থূলকোণ","গ":"সমকোণ","ঘ":"সরলকোণ"}'::jsonb, 'ক', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, null, 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'নিচের কোনটি সঠিক?', 'mcq', '{"ক":"∠QPR = ∠PQR","খ":"∠QPR = ∠QSR","গ":"1/2∠PSQ = ∠PRQ","ঘ":"1/2∠PNQ = ∠PSQ"}'::jsonb, 'খ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর — কিন্তু চিত্রটি ছাপায় নেই (PDF p48-এ Q22-এর কোনো চিত্র রেন্ডার হয়নি); উদ্দীপকের লেখা ও চাবি ছাপা অনুযায়ী রাখা হলো।', 'নিচের চিত্রের আলোকে ২ ও ৩ নং প্রশ্নের উত্তর দাও: চিত্রে, ∠QPR, ∠PQR এর সমদ্বিখণ্ডক M বিন্দুতে এবং ∠PQS ও ∠QPS এর সমদ্বিখণ্ডক N বিন্দুতে মিলিত হয়। আবার PQ ≠ RS ≠ PS।', 'jessore', 2023, 'diagram'),
  ('math-board-jessore-2023-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'চিত্রে—
i. P, Q, M, N বিন্দু চারটি সমবৃত্ত
ii. ∠QSR = 180° − ∠PQR
iii. 1/2∠PRQ = ∠PMQ − 90°
নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর — কিন্তু চিত্রটি ছাপায় নেই (PDF p48-এ Q22-এর কোনো চিত্র রেন্ডার হয়নি); উদ্দীপকের লেখা ও চাবি ছাপা অনুযায়ী রাখা হলো।', 'নিচের চিত্রের আলোকে ২ ও ৩ নং প্রশ্নের উত্তর দাও: চিত্রে, ∠QPR, ∠PQR এর সমদ্বিখণ্ডক M বিন্দুতে এবং ∠PQS ও ∠QPS এর সমদ্বিখণ্ডক N বিন্দুতে মিলিত হয়। আবার PQ ≠ RS ≠ PS।', 'jessore', 2023, 'diagram'),
  ('math-board-jessore-2023-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p48', 'চিত্রে, O কেন্দ্রবিশিষ্ট বৃত্তে DA ও DC দুইটি স্পর্শক। চিত্রানুসারে—
