  ('math-board-jessore-2023-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', 'প্রচুরক শ্রেণির মধ্যমান কত?', 'mcq', '{"ক":"43","খ":"28","গ":"33","ঘ":"38"}'::jsonb, 'ঘ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে ৫ ও ৬ নং প্রশ্নের উত্তর দাও: শ্রেণী ব্যাপ্তি 21-25, 26-30, 31-35, 36-40, 41-45; গণসংখ্যা 3, 6, 6, 7, 4।', 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', 'মধ্যক নির্ণয়ের জন্য Fc এর মান নিচের কোনটি?', 'mcq', '{"ক":"6","খ":"7","গ":"9","ঘ":"15"}'::jsonb, 'গ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে ৫ ও ৬ নং প্রশ্নের উত্তর দাও: শ্রেণী ব্যাপ্তি 21-25, 26-30, 31-35, 36-40, 41-45; গণসংখ্যা 3, 6, 6, 7, 4।', 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', 'একটি রম্বসের দুইটি কর্ণের দৈর্ঘ্য 8 একক ও 12 একক হলে এর ক্ষেত্রফল কত?', 'mcq', '{"ক":"40 বর্গ একক","খ":"48 বর্গ একক","গ":"96 বর্গ একক","ঘ":"192 বর্গ একক"}'::jsonb, 'খ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, null, 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', 'কোনো ত্রিভুজের দুইটি বাহুর দৈর্ঘ্য 7 সে.মি. ও 12 সে.মি. এবং এদের অন্তর্ভুক্ত কোণ 30° হলে ত্রিভুজটির ক্ষেত্রফল কত?', 'mcq', '{"ক":"21 বর্গ সে.মি.","খ":"42 বর্গ সে.মি.","গ":"21√3 বর্গ সে.মি.","ঘ":"42√3 বর্গ সে.মি."}'::jsonb, 'ক', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', null, null, 'jessore', 2023, null),
  ('math-board-jessore-2023-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', '2∠OAB = কত?', 'mcq', '{"ক":"60°","খ":"90°","গ":"120°","ঘ":"135°"}'::jsonb, 'ঘ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: সুষম অষ্টভুজ ABCDEFGH, কেন্দ্র O, OA = 2 cm।', 'নিচের চিত্রের আলোকে ৯ ও ১০ নং প্রশ্নের উত্তর দাও: চিত্রে, ABCDEFGH বহুভুজের কেন্দ্র O এবং OA = 2 cm।', 'jessore', 2023, 'diagram'),
  ('math-board-jessore-2023-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', 'বহুভুজটির ক্ষেত্রফল কত?', 'mcq', '{"ক":"6√2 cm²","খ":"8√2 cm²","গ":"6√3 cm²","ঘ":"8√3 cm²"}'::jsonb, 'খ', null, 1, false, 'math-board-jessore-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: সুষম অষ্টভুজ ABCDEFGH, কেন্দ্র O, OA = 2 cm।', 'নিচের চিত্রের আলোকে ৯ ও ১০ নং প্রশ্নের উত্তর দাও: চিত্রে, ABCDEFGH বহুভুজের কেন্দ্র O এবং OA = 2 cm।', 'jessore', 2023, 'diagram'),
  ('math-board-sylhet-2023-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', '2 বছরে তার মুনাফা কত?', 'mcq', '{"ক":"250 টাকা","খ":"500 টাকা","গ":"1000 টাকা","ঘ":"2000 টাকা"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', 'উদ্দীপকে বোর্ডের মূল নম্বর (২৯ ও ৩০ নং) ছাপা; এই সেটে প্রশ্ন নং ১ ও ২।', 'নিচের তথ্যের আলোকে ২৯ ও ৩০ নং প্রশ্নের উত্তর দাও: কামাল উদ্দিন 5% হার সরল মুনাফায় 5 বছরের জন্য 5000 টাকা ''AB'' ব্যাংকে জমা রাখেন।', 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p49', '5 বছর পরে সে মুনাফা-আসলে কত টাকা পাবে?', 'mcq', '{"ক":"6250 টাকা","খ":"6000 টাকা","গ":"5500 টাকা","ঘ":"5250 টাকা"}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে ২৯ ও ৩০ নং প্রশ্নের উত্তর দাও: কামাল উদ্দিন 5% হার সরল মুনাফায় 5 বছরের জন্য 5000 টাকা ''AB'' ব্যাংকে জমা রাখেন।', 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p50', 'C = {a, b} এবং D = {b, d} হলে, (C \ D) কোনটি?', 'mcq', '{"ক":"{a, d}","খ":"{a}","গ":"{a, d, b}","ঘ":"∅"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p50', 'x + 1/x = 2√2 যেখানে x > 0, x − 1/x এর মান কত?', 'mcq', '{"ক":"2","খ":"2√3","গ":"6","ঘ":"10"}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p50', 'p² − 1 = √5p হলে, যেখানে p > 0—
