  ('math-board-sylhet-2023-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p51', 'একটি ত্রিভুজের তিনটি কোণের পরিমাপ যথাক্রমে 30°, 60° ও 90° হলে, ত্রিভুজটি কোন ধরনের ত্রিভুজ?', 'mcq', '{"ক":"স্থূলকোণী","খ":"সূক্ষ্মকোণী","গ":"সমকোণী","ঘ":"সমদ্বিবাহু"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p51', 'A = {1, 2}, B = {2, 3} এবং C = {3, 4, 5}, হলে A ∪ B ∪ C এর উপাদান সংখ্যা কত?', 'mcq', '{"ক":"3","খ":"4","গ":"5","ঘ":"6"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', 'ছাপায় C = (3, 4, 5) বন্ধনীতে লেখা; সেট হিসেবে {3, 4, 5} ধরা হয়েছে।', null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p52', 'চিত্রের গাঢ় অংশটি নিচের কোনটি নির্দেশ করে?', 'mcq', '{"ক":"A ∪ B","খ":"A ∩ B","গ":"A \\ B","ঘ":"B \\ A"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: ভেন চিত্রে A ও B দুটি বৃত্ত; A-এর যে অংশ B-এর বাইরে, সেটি গাঢ় করা। প্রশ্নের লেখা চিত্রের নিচে ছাপা।', null, 'sylhet', 2023, 'diagram'),
  ('math-board-sylhet-2023-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p52', 'A = {2, 3, 5, 7}-এর সেট গঠনরূপ কোনটি?', 'mcq', '{"ক":"{x ∈ N : x মৌলিক সংখ্যা এবং x ≤ 7}","খ":"{x ∈ N : x বিজোড় সংখ্যা এবং x ≤ 7}","গ":"{x ∈ N : x মৌলিক সংখ্যা এবং x ≤ 11}","ঘ":"{x ∈ N : x মৌলিক সংখ্যা এবং x < 7}"}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p52', 'sinθ(√(1 + tan²θ)) = কত?', 'mcq', '{"ক":"cosecθ","খ":"secθ","গ":"cotθ","ঘ":"tanθ"}'::jsonb, 'ঘ', null, 1, false, 'math-board-sylhet-2023-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2023, null),
  ('math-board-sylhet-2023-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p53', 'উপরের চিত্রে—
