  ('math-board-chattogram-2023-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p66', '-2 + 2 − 2 + 2 − . . . . . . . . গুণোত্তর ধারাটির সাধারণ অনুপাত কত?', 'mcq', '{"ক":"−4","খ":"−1","গ":"1","ঘ":"4"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p66', 'কোনো শ্রেণির ঊর্ধ্বসীমা 37 এবং শ্রেণির মধ্যমান 34 হলে, ঐ শ্রেণির নিম্নসীমা কত?', 'mcq', '{"ক":"40","খ":"35.5","গ":"34","ঘ":"34"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'ছাপার ভুল: গ ও ঘ দুটোতেই 34 ছাপা; সঠিক নিম্নসীমা 2×34 − 37 = 31, যা কোনো অপশনে নেই; চাবি ছাপা অনুযায়ী ঘ রাখা হলো।', null, 'chattogram', 2023, null),
