  ('math-board-chattogram-2023-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', 'A = {2, 4, 6}, B = {1, 3, 5} হলে, A × B এর উপাদান সংখ্যা কতটি?', 'mcq', '{"ক":"6 টি","খ":"8 টি","গ":"9 টি","ঘ":"16 টি"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'ছাপায় ''A {2, 4, 6}'' — ''='' চিহ্ন নেই; A = {2, 4, 6} ধরা হয়েছে।', null, 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', '81 এর √3 ভিত্তিক লগারিদম কত?', 'mcq', '{"ক":"8","খ":"4","গ":"1/4","ঘ":"1/8"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', 'sinθ = 1/2 হলে, cos²θ = ?', 'mcq', '{"ক":"2/√3","খ":"√3/2","গ":"3/4","ঘ":"1/4"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', '0.0332 সংখ্যাটির বৈজ্ঞানিক রূপ কোনটি?', 'mcq', '{"ক":"332 × 10⁻²","খ":"3.32 × 10⁻²","গ":"33.2 × 10⁻³","ঘ":"0.332 × 10⁻¹"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', 'চিত্রে ABCD বৃত্তের কেন্দ্র হলে, ∠BAD + ∠BCD এর মান কত?', 'mcq', '{"ক":"90°","খ":"180°","গ":"270°","ঘ":"360°"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: বৃত্তে অন্তর্লিখিত চতুর্ভুজ ABCD (A উপরে, B ডানে, C নিচে-ডানে, D বামে)। প্রশ্নের বাক্যটি ছাপায় ভাঙা (''ABCD বৃত্তের কেন্দ্র হলে'') — সম্ভবত ''বৃত্তে অন্তর্লিখিত চতুর্ভুজ হলে'' বোঝানো হয়েছে; বিপ্রতীপ কোণের সমষ্টি 180° (চাবি খ)।', null, 'chattogram', 2023, 'diagram'),
  ('math-board-chattogram-2023-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', '∠x = কত?', 'mcq', '{"ক":"120°","খ":"135°","গ":"140°","ঘ":"145°"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: সুষম ষড়ভুজ ABCDEF, B শীর্ষের অন্তঃস্থ কোণ x চিহ্নিত। উদ্দীপকে বোর্ডের মূল নম্বর (১৯ ও ২০ নং) ছাপা; এই সেটে প্রশ্ন নং ২৫ ও ২৬।', 'নিচের তথ্যের আলোকে ১৯ ও ২০ নং প্রশ্নের উত্তর দাও: চিত্রে, ABCDEF একটি সুষম ষড়ভুজ যার বাহুর দৈর্ঘ্য 2 সে.মি.।', 'chattogram', 2023, 'diagram'),
  ('math-board-chattogram-2023-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p67', 'বহুভুজটির ক্ষেত্রফল কত?', 'mcq', '{"ক":"6/√3 বর্গ সে.মি.","খ":"2√3 বর্গ সে.মি.","গ":"6√3 বর্গ সে.মি.","ঘ":"12√3 বর্গ সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: সুষম ষড়ভুজ ABCDEF, বাহুর দৈর্ঘ্য 2 সে.মি.।', 'নিচের তথ্যের আলোকে ১৯ ও ২০ নং প্রশ্নের উত্তর দাও: চিত্রে, ABCDEF একটি সুষম ষড়ভুজ যার বাহুর দৈর্ঘ্য 2 সে.মি.।', 'chattogram', 2023, 'diagram'),
  ('math-board-chattogram-2023-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'a = b হলে, x = কত?', 'mcq', '{"ক":"−2","খ":"−1","গ":"","ঘ":"1"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'ছাপায় গ অপশন অনুপস্থিত (শুধু ক, খ, ঘ ছাপা); গ-র মান ছাপায় নেই বলে অপশন খালি রাখা হলো — গণনা করে বসানো হয়নি (ছাপা চাবি গ)। উদ্দীপকে বোর্ডের মূল নম্বর (১১ ও ১২ নং) ছাপা; এই সেটে প্রশ্ন নং ২৭ ও ২৮।', 'নিচের তথ্যের আলোকে ১১ ও ১২ নং প্রশ্নের উত্তর দাও: 3^x = a, 9^(−x) = b।', 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'নিচের কোন সম্পর্কটি সঠিক?', 'mcq', '{"ক":"ab² = 1","খ":"a/b² = 1","গ":"b²/a = 3","ঘ":"a²b = 1"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে ১১ ও ১২ নং প্রশ্নের উত্তর দাও: 3^x = a, 9^(−x) = b।', 'chattogram', 2023, null),
  ('math-board-chattogram-2023-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'OP-এর দৈর্ঘ্য কত?', 'mcq', '{"ক":"3 সে.মি.","খ":"4 সে.মি.","গ":"5 সে.মি.","ঘ":"7 সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: O কেন্দ্রবিশিষ্ট বৃত্তে PQ জ্যা, S পরিধির উপরের বিন্দু, OR ⊥ PQ (R পাদবিন্দু), OR = 3 সে.মি., PR = 4 সে.মি.। উদ্দীপকে বোর্ডের মূল নম্বর (৪ ও ৫ নং) ছাপা; এই সেটে প্রশ্ন নং ২৯ ও ৩০।', 'নিচের চিত্রের আলোকে ৪ ও ৫ নং প্রশ্নের উত্তর দাও: চিত্রের PQS বৃত্তের কেন্দ্র O, OR 3 সে.মি. ও PR = 4 সে.মি.।', 'chattogram', 2023, 'diagram'),
  ('math-board-chattogram-2023-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'চিত্রানুসারে—
i. PQ-এর সমদ্বিখণ্ডক OR
ii. PQ চাপের ওপর দণ্ডায়মান বৃত্তস্থ ∠PSQ
iii. PQ < OP + OQ
নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: ২৯ নং প্রশ্নের চিত্র (O কেন্দ্র, PQ জ্যা, S পরিধির বিন্দু, OR ⊥ PQ)।', 'নিচের চিত্রের আলোকে ৪ ও ৫ নং প্রশ্নের উত্তর দাও: চিত্রের PQS বৃত্তের কেন্দ্র O, OR 3 সে.মি. ও PR = 4 সে.মি.।', 'chattogram', 2023, 'diagram'),
  ('math-board-rajshahi-2023-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'তিনটি বাহুর দৈর্ঘ্য দেওয়া থাকলে নিচের কোন ক্ষেত্রে একটি সমকোণী ত্রিভুজ আঁকা যায়?', 'mcq', '{"ক":"2 cm, 3 cm, 6 cm","খ":"3 cm, 4 cm, 5 cm","গ":"4 cm, 5 cm, 6 cm","ঘ":"3 cm, 4 cm, 8 cm"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2023-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2023, null),
  ('math-board-rajshahi-2023-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'উপরের চিত্রে, tanθ · cotθ এর মান কত?', 'mcq', '{"ক":"1","খ":"8","গ":"2√2","ঘ":"1/(2√2)"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2023-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: সমকোণী ত্রিভুজ ABC (∠B = 90°), AB = 2√2, BC = 2, ∠C = θ।', null, 'rajshahi', 2023, 'diagram'),
  ('math-board-rajshahi-2023-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p68', 'কোনো বৃত্তের উপচাপে অন্তর্লিখিত কোণ—', 'mcq', '{"ক":"সূক্ষ্মকোণ","খ":"স্থূলকোণ","গ":"সমকোণ","ঘ":"পূরককোণ"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2023-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2023, null),
