  ('math-board-rajshahi-2023-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p69', 'যদি x² + y² = 9 এবং xy = 3 হয়, তবে (x + y)² এর মান কত?', 'mcq', '{"ক":"3","খ":"15","গ":"6","ঘ":"9"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2023-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2023, null),
  ('math-board-rajshahi-2023-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p69', '(4ⁿ − 1)/(2ⁿ + 1) এর মান নিচের কোনটি?', 'mcq', '{"ক":"2ⁿ + 1","খ":"2ⁿ − 1","গ":"2^(n+1)","ঘ":"2^(n−1)"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2023-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2023, null),
  ('math-board-rajshahi-2023-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p69', 'চিত্রে—
