  ('math-board-mymensingh-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p2', 'প্রচুরক নিচের কোনটি?', 'mcq', '{"ক":"36.25","খ":"38.75","গ":"41.67","ঘ":"55.00"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, 'শ্রেণি ব্যাপ্তি: 20-24, 25-29, 30-34, 35-39, 40-44, 45-49; গণসংখ্যা: 3, 7, 8, 10, 4, 2', 'mymensingh', 2024, null),
