  ('math-board-mymensingh-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p2', '△PDE : △PQR = কত?', 'mcq', '{"ক":"1:2","খ":"2:1","গ":"1:4","ঘ":"4:1"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', 'চিত্র: শীর্ষবিন্দু P-বিশিষ্ট ত্রিভুজ PQR; DE, PQ ও PR-এর মধ্যবিন্দু সংযোগকারী রেখাংশ; PS, QR-এর ওপর S বিন্দুতে লম্ব।', 'চিত্রে PD = DQ, PE = ER এবং ∠QPS = ∠RPS', 'mymensingh', 2024, 'diagram'),
  ('math-board-mymensingh-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p2', 'চিত্রে-
