  ('math-board-mymensingh-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p4', 'চিত্রে O কেন্দ্রবিশিষ্ট বৃত্তে AB ব্যাস হলে ∠ACD = কত?', 'mcq', '{"ক":"20°","খ":"35°","গ":"55°","ঘ":"70°"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', 'চিত্র: O কেন্দ্রবিশিষ্ট বৃত্ত, AB ব্যাস; বৃত্তের ওপর D ও C বিন্দু; ∠CAB = 20° চিহ্নিত; DC ও DA বাহুতে সমান চিহ্ন (সমান বাহু) দেওয়া আছে।', null, 'mymensingh', 2024, 'diagram'),
  ('math-board-mymensingh-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p4', 'বৃত্তের বহিঃস্থ কোনো বিন্দু থেকে ঐ বৃত্তে সর্বোচ্চ কয়টি স্পর্শক আঁকা যায়?', 'mcq', '{"ক":"1","খ":"2","গ":"3","ঘ":"4"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2024, null),
