  ('math-board-mymensingh-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p4', 'সমানুপাতের উদাহরণ নিচের কোনটি?', 'mcq', '{"ক":"3:4 = 4:3","খ":"2:3 = 6:10","গ":"3:2 = 9:6","ঘ":"2:5 = 4:25"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2024, null),
