  ('math-board-mymensingh-2024-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'রম্বসের প্রতিসাম্য রেখা কয়টি?', 'mcq', '{"ক":"1 টি","খ":"2 টি","গ":"3 টি","ঘ":"4 টি"}'::jsonb, 'খ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2024, null),
  ('math-board-mymensingh-2024-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'সামান্তরিকের ভূমি 9 সেমি ও উচ্চতা 4 সেমি হলে এর ক্ষেত্রফল কত?', 'mcq', '{"ক":"18 বর্গসেমি","খ":"26 বর্গসেমি","গ":"36 বর্গসেমি","ঘ":"72 বর্গসেমি"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2024, null),
  ('math-board-mymensingh-2024-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', '1.4̇3̇ এর সাধারণ ভগ্নাংশ কোনটি?', 'mcq', '{"ক":"142/99","খ":"143/99","গ":"142/100","ঘ":"143/100"}'::jsonb, 'ক', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', null, null, 'mymensingh', 2024, null),
  ('math-board-mymensingh-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'f(x) এর একটি উৎপাদক (2x + 1) হলে নিচের কোনটি ০ (শূন্য) হবে?', 'mcq', '{"ক":"f(−1)","খ":"f(1)","গ":"f(−1/2)","ঘ":"f(1/2)"}'::jsonb, 'গ', null, 1, false, 'math-board-mymensingh-2024-mcq', false, null, 'board-mcq', 'এক্সট্রাক্টে f-এর জায়গায় ∫ চিহ্ন এসেছে; PDF-তে f(x) ছাপা আছে।', null, 'mymensingh', 2024, null),
  ('math-board-barishal-2024-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'OE = OF হলে CD = কত সেমি?', 'mcq', '{"ক":"3","খ":"4","গ":"6","ঘ":"8"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে বৃত্তের কেন্দ্র O, AB ও CD জ্যা, E ও F লম্বের পাদবিন্দু এবং BE = 4 সেমি দেখা যায়।', 'চিত্রে O বৃত্তটির কেন্দ্র এবং BE = 4 সেমি। চিত্রে বৃত্তের ভিতরে AB ও CD দুইটি সমান্তরাল জ্যা; O থেকে AB-এর উপর লম্বের পাদবিন্দু E এবং CD-এর উপর লম্বের পাদবিন্দু F; EF রেখাংশ O দিয়ে যায়।', 'barishal', 2024, 'diagram'),
  ('math-board-barishal-2024-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'AB = CD এবং OE = 3 সেমি হলে বৃত্তটির ব্যাস কত সেমি?', 'mcq', '{"ক":"4","খ":"5","গ":"6","ঘ":"10"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে বৃত্তের কেন্দ্র O, AB ও CD জ্যা, E ও F লম্বের পাদবিন্দু এবং BE = 4 সেমি দেখা যায়।', 'চিত্রে O বৃত্তটির কেন্দ্র এবং BE = 4 সেমি। চিত্রে বৃত্তের ভিতরে AB ও CD দুইটি সমান্তরাল জ্যা; O থেকে AB-এর উপর লম্বের পাদবিন্দু E এবং CD-এর উপর লম্বের পাদবিন্দু F; EF রেখাংশ O দিয়ে যায়।', 'barishal', 2024, 'diagram'),
  ('math-board-barishal-2024-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', '3 + 5 + 7 + . . . . . . . . . . . ধারাটির ১ম n সংখ্যক পদের সমষ্টি কত?', 'mcq', '{"ক":"n²","খ":"n(n+1)","গ":"n(n+2)","ঘ":"n(n+3)"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p5', 'নিচের কোনটিকে শূন্যমাত্রার সত্তা বলে গণ্য করা হয়?', 'mcq', '{"ক":"রেখা","খ":"তল","গ":"কোণ","ঘ":"বিন্দু"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'ΔABC এর AB = AC হলে 1/2 ∠ACD = কত ডিগ্রি?', 'mcq', '{"ক":"55°","খ":"90°","গ":"110°","ঘ":"140°"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: ∠A = 40° মানটি শুধু চিত্রে দেওয়া, প্রশ্নের লেখায় নেই; BC-কে D পর্যন্ত বর্ধিত করা চিত্রে দেখা যায়।', 'চিত্রে ΔABC-এর ∠A = 40° এবং BC বাহুকে D পর্যন্ত বর্ধিত করা হয়েছে।', 'barishal', 2024, 'diagram'),
  ('math-board-barishal-2024-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'একটি সমদ্বিবাহু সমকোণী ত্রিভুজের সমান বাহুদ্বয়ের প্রতিটির দৈর্ঘ্য 6 সেমি। ত্রিভুজটির ক্ষেত্রফল কত বর্গ সেমি?', 'mcq', '{"ক":"72","খ":"36","গ":"18","ঘ":"12"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'নিম্নের উপাত্তের প্রচুরক কত?', 'mcq', '{"ক":"61","খ":"55.5","গ":"52.43","ঘ":"45"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'ছাপা উত্তর ক (61) সারণি থেকে প্রচুরকের প্রচলিত সূত্রে মেলে না — সূত্রে প্রচুরক ≈ 52.43 (গ অপশন) আসে; ছাপা অনুযায়ীই লেখা হয়েছে, উত্তর যাচাই করা হয়নি।', 'সারণি — শ্রেণি (x): 21-30, 31-40, 41-50, 51-60; গণসংখ্যা (f): 5, 8, 10, 12।', 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', '0.13̇ ÷ 0.3̇ = কত?', 'mcq', '{"ক":"2/45","খ":"2/5","গ":"9/4","ঘ":"4"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'আবৃত্ত দশমিকের বিন্দু (ডট) দুইটি সংখ্যারই 3-এর উপরে ছাপা — প্রথমটিতে 0.13̇ (ডট শুধু 3-এর উপরে), দ্বিতীয়টিতে 0.3̇।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'নিচের কোনটি সসীম সেট?', 'mcq', '{"ক":"{x ∈ Z : x < 2}","খ":"{p/q : p ও q পূর্ণসংখ্যা এবং q ≠ 0}","গ":"{y ∈ N : y² < 100 < y³}","ঘ":"{x ∈ Z : x² > 5 এবং x³ ≤"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'ঘ অপশনটি ছাপায় অসম্পূর্ণ — ''x³ ≤'' পর্যন্ত ছাপা, তার পরের সীমাটি PDF-এ নেই; ছাপা অনুযায়ীই লেখা হয়েছে। খ অপশনের ''p ও q পূর্ণসংখ্যা'' অংশটি ওয়াটারমার্কের নিচে থাকলেও পড়া গেছে।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'f(x) = 3/x + 1 হলে f(1/x) = কত?', 'mcq', '{"ক":"3x+1","খ":"3+x","গ":"(3+x)/x","ঘ":"x/(3x+1)"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'a + 1/a = 3 হলে 2a/(3a² − 2a + 3) এর মান কত?', 'mcq', '{"ক":"−2/11","খ":"−2/7","গ":"2/11","ঘ":"2/7"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'টেক্সট এক্সট্রাক্টে ভগ্নাংশটি ভাঙা ছিল; PDF ছবি দেখে যাচাই করা হয়েছে — লব 2a, হর 3a² − 2a + 3।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', '5% সরল মুনাফায় 400 টাকা কত বছরে মুনাফা-আসলে 520 টাকা হবে?', 'mcq', '{"ক":"4","খ":"6","গ":"24","ঘ":"46"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', '1/(5^(−x+1)) = 625 হলে x এর মান কত?', 'mcq', '{"ক":"3","খ":"4","গ":"5","ঘ":"6"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'ছাপায় ভগ্নাংশ আকারে — লব 1, হর 5^(−x+1); রৈখিক লেখায় 1/(5^(−x+1)) লেখা হয়েছে।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'একটি হাইড্রোজেন পরমাণুর ব্যাসার্ধ 0.0000000037 সেমি.। সংখ্যাটির- i. আদর্শরূপ = 3.7 × 10⁻⁹ ii. সাধারণ লগের পূর্ণক = 9̄ iii. সাধারণ লগের অংশক = 0.5682 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'ii-তে পূর্ণক 9-এর উপরে বার (9̄) ছাপা — টেক্সট এক্সট্রাক্টে বারটি হারিয়ে গিয়েছিল, PDF ছবিতে যাচাই করা হয়েছে।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p6', 'x − 2 = (x−2)/2 সমীকরণের সমাধান সেট কোনটি?', 'mcq', '{"ক":"{ }","খ":"{1}","গ":"{2}","ঘ":"{1, 2}"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'ছাপা সমীকরণটি সমাধান করলে শুধু x = 2 আসে, কিন্তু ছাপা উত্তর ঘ ({1, 2}); ছাপা প্রশ্ন ও উত্তর পরস্পর মেলে না — ছাপা অনুযায়ীই লেখা হয়েছে।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', '−1/2 x + y = −1, x − 2y = 2 সমীকরণ জোটটি - i. সমঞ্জস ii. পরস্পর নির্ভরশীল iii. একটিমাত্র সমাধান আছে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'প্রথম সমীকরণটি −(1/2)x + y = −1 (ভগ্নাংশ আকারে ছাপা); দুই সমীকরণ একই সরলরেখা প্রকাশ করে বলে জোটটি পরস্পর নির্ভরশীল।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'sin θ √(1 + tan²θ) = কত?', 'mcq', '{"ক":"tanθ","খ":"sinθ","গ":"cosθ","ঘ":"secθ"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'টেক্সট এক্সট্রাক্টে বর্গমূলের ভিতরটা ভাঙা ছিল; PDF ছবিতে যাচাই করা হয়েছে — √(1 + tan²θ)।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', '0° ≤ θ ≤ 90° এর জন্য sinθ এর সর্বনিম্ন মান কত?', 'mcq', '{"ক":"−1","খ":"","গ":"1","ঘ":"∞"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'খ অপশনটি PDF-এ ছাপা নেই (শুধু ক, গ, ঘ দৃশ্যমান — p7 ছবিতে যাচাই করা); ছাপা উত্তর খ — খ-এর মান ছাপা থেকে পাওয়া যায়নি বলে খালি রাখা হয়েছে, আন্দাজে বসানো হয়নি।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'ΔABC এর ∠C = এক সমকোণ এবং ∠A = 60° হলে (tan A − tan B)/(1 + tan A − tan B) এর মান কত?', 'mcq', '{"ক":"√3","খ":"1","গ":"1/√3","ঘ":""}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'হরে ছাপায় ''1 + tan A − tan B'' লেখা; ছাপা উত্তর গ (1/√3) tan(A−B) সূত্রের (হর 1 + tan A tan B) সঙ্গে মেলে, ছাপা ভগ্নাংশের সঙ্গে নয় — ছাপা অনুযায়ীই লেখা হয়েছে। ঘ অপশনটি PDF-এ ছাপা নেই (শুধু ক, খ, গ দৃশ্যমান)।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', '12 মিটার দীর্ঘ একটি মই দেওয়াল থেকে 6√3 মিটার দূরে ভূমির সাথে কোণ উৎপন্ন করে দেওয়ালের ছাদ স্পর্শ করে। θ এর মান কত?', 'mcq', '{"ক":"30°","খ":"45°","গ":"60°","ঘ":"90°"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'প্রশ্নের প্রথম বাক্যে θ চিহ্ন ছাপা নেই (''ভূমির সাথে কোণ উৎপন্ন করে''); দ্বিতীয় বাক্যে θ-এর মান চাওয়া হয়েছে — ছাপা অনুযায়ীই লেখা হয়েছে।', null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'কোনো বর্গক্ষেত্র তার কর্ণের উপর অঙ্কিত বর্গক্ষেত্রের কত গুণ?', 'mcq', '{"ক":"অর্ধেক","খ":"সমান","গ":"দেড়গুণ","ঘ":"দ্বিগুণ"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'π সেমি পরিধিবিশিষ্ট বৃত্তের ক্ষেত্রফল কত বর্গসেমি?', 'mcq', '{"ক":"π/2","খ":"π/3","গ":"π/4","ঘ":"π/8"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'একটি ঘনকের সম্পূর্ণ পৃষ্ঠের ক্ষেত্রফল 150 বর্গমি.। এর পৃষ্ঠতলের কর্ণের দৈর্ঘ্য কত মিটার?', 'mcq', '{"ক":"5","খ":"5√2","গ":"5√3","ঘ":"125"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'একটি সমবৃত্তভূমিক বেলনের ভূমির ব্যাসার্ধ ও উচ্চতা পরস্পর সমান। বেলনটির সমগ্রতল ও বক্রতলের ক্ষেত্রফলের অনুপাত কত হবে?', 'mcq', '{"ক":"3:1","খ":"2:1","গ":"1:1","ঘ":"1:2"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', 'নিচের কোনটি নির্ণয়ে ধাপ বিচ্যুতি প্রয়োজন হয়?', 'mcq', '{"ক":"গড়","খ":"মধ্যক","গ":"প্রচুরক","ঘ":"পরিসর"}'::jsonb, 'ক', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p7', '12 থেকে 45 পর্যন্ত মৌলিক সংখ্যাগুলোর মধ্যক নিচের কোনটি?', 'mcq', '{"ক":"52","খ":"29","গ":"26","ঘ":"23"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p8', 'চিত্রে, BC || PQ হলে- i. ΔBO ও ΔPOQ সদৃশ ii. AP : BP = AQ : CQ iii. BO : OQ = CO : OP নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে ΔABC, AB-তে P, AC-তে Q, PQ || BC, BQ ও CP-এর ছেদবিন্দু O দেখা যায়। i নং উক্তিতে ছাপায় প্রথম ত্রিভুজের নাম ''ΔBO'' লেখা (তৃতীয় শীর্ষবিন্দু নেই); চিত্র ও iii নং উক্তি অনুযায়ী এটি ΔBOC হওয়ার কথা, কিন্তু ছাপা অনুযায়ীই লেখা হয়েছে।', 'চিত্রে ΔABC-এর AB বাহুর উপর P এবং AC বাহুর উপর Q বিন্দু; PQ || BC; BQ ও CP পরস্পরকে O বিন্দুতে ছেদ করেছে।', 'barishal', 2024, 'diagram'),
  ('math-board-barishal-2024-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p8', '''T'' বর্ণটির মোট কতটি প্রতিসাম্য রেখা আছে?', 'mcq', '{"ক":"শূন্যটি","খ":"একটি","গ":"তিনটি","ঘ":"অসংখ্য"}'::jsonb, 'খ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', null, null, 'barishal', 2024, null),
  ('math-board-barishal-2024-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p8', '∠BOC এর মান কত?', 'mcq', '{"ক":"300°","খ":"270°","গ":"120°","ঘ":"90°"}'::jsonb, 'গ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে বৃত্তের কেন্দ্র O, বহিঃস্থ বিন্দু A থেকে AB ও AC দুইটি স্পর্শক, B ও C স্পর্শবিন্দু, D বৃহৎ চাপ BDC-এর উপর অবস্থিত এবং OB, OC, DB, DC জ্যা/ব্যাসার্ধ আঁকা আছে। ছাপায় কেন্দ্রের নাম O লেখা নেই (''চিত্রে বৃত্তের কেন্দ্র।''), O চিত্রে দেখা যায়; 60°-এর পরে একটি অতিরিক্ত ''1'' ছাপা আছে, তা বাদ দেওয়া হয়েছে।', 'চিত্রে বৃত্তের কেন্দ্র। AB ও AC দুইটি স্পর্শক এবং ∠BAC = 60°', 'barishal', 2024, 'diagram'),
  ('math-board-barishal-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p8', 'D, BDC চাপের মধ্যবিন্দু হলে - i. ∠BDC = ∠BAC ii. ∠BOC = ∠BAC iii. ∠BCD + ∠DBC = ∠BOC নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-barishal-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে বৃত্তের কেন্দ্র O, বহিঃস্থ বিন্দু A থেকে AB ও AC দুইটি স্পর্শক, B ও C স্পর্শবিন্দু, D বৃহৎ চাপ BDC-এর উপর অবস্থিত। ii নং উক্তিটি ছাপা অনুযায়ী ''∠BOC = ∠BAC'' (ছাপায় ''ii.'' দুইবার লেখা), যা গাণিতিকভাবে ভুল (120° ≠ 60°); ছাপা উত্তর ঘ (সব সঠিক) — সম্ভবত ছাপায় ''∠BOC = 2∠BAC'' হওয়ার কথা ছিল; ছাপা অনুযায়ীই লেখা হয়েছে।', 'চিত্রে বৃত্তের কেন্দ্র। AB ও AC দুইটি স্পর্শক এবং ∠BAC = 60°', 'barishal', 2024, 'diagram'),
  ('math-board-dinajpur-2024-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p8', 'সমবৃত্তভূমিক কেলনের ভূমির ব্যাসার্ধ 5 সে.মি. এবং উচ্চতা 7 সে.মি. হলে, এর -
i. ভূমির ক্ষেত্রফল = 25π বর্গ সে.মি.
ii. বক্রতলের ক্ষেত্রফল = 70π বর্গ সে.মি.
iii. আয়তন = 350π ঘন সে.মি.
নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'ছাপায় iii-এ আয়তন 350π লেখা আছে (গাণিতিকভাবে π×5²×7 = 175π হতো); ছাপা মানই হুবহু রাখা হয়েছে।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', '1 থেকে 19 পর্যন্ত মৌলিক সংখ্যাগুলোর গড় কত?', 'mcq', '{"ক":"9.63","খ":"9.5","গ":"8.67","ঘ":"8.23"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'কোনো দণ্ডের ছায়ার দৈর্ঘ্য তার দৈর্ঘ্যের কতগুণ হলে উন্নতি কোণ 30° হবে?', 'mcq', '{"ক":"1/√3","খ":"1/√2","গ":"√2","ঘ":"√3"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'বর্গের প্রতিসাম্য রেখা কয়টি?', 'mcq', '{"ক":"4","খ":"3","গ":"2","ঘ":"1"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'ΔABC এর AB ও BC এর মধ্যবিন্দু যথাক্রমে D ও E হলে, ΔBDE : ΔABC = কত?', 'mcq', '{"ক":"2:3","খ":"1:2","গ":"1:3","ঘ":"1:4"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'ক অপশন ছাপায় ''2 3'' আকারে, কোলন অস্পষ্ট; অনুপাত ধরে 2:3 লেখা হয়েছে।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'π মিটার পরিধিবিশিষ্ট বৃত্তের ক্ষেত্রফল কত বর্গমিটার?', 'mcq', '{"ক":"π/4","খ":"π/2","গ":"π","ঘ":"2π"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'একটি সমবাহু ত্রিভুজের ক্ষেত্রফল 25√3 বর্গমিটার হলে ত্রিভুজটির বাহুর দৈর্ঘ্য কত মিটার?', 'mcq', '{"ক":"5","খ":"10","গ":"50","ঘ":"100"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'ক্রমযোজিত গণসংখ্যা প্রয়োজন -
i. মধ্যক নির্ণয়ে
