  ('math-board-dinajpur-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'উপাত্তের সর্বোচ্চ মান 97, পরিসর 48 হলে, সর্বনিম্ন মান কত?', 'mcq', '{"ক":"51","খ":"50","গ":"49","ঘ":"48"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'নিচের কোনটি অমূলদ সংখ্যা?', 'mcq', '{"ক":"³√64/√36","খ":"√32/√64","গ":"√(81/625)","ঘ":"³√8/³√27"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'যদি f(x) = x³ + ax² − 6x − 9 হয়, তবে a এর কোন মানের জন্য f(−3) = 0 হবে?', 'mcq', '{"ক":"6","খ":"2","গ":"-2","ঘ":"-4"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'a(2a − 3) = 1/2 হলে-
i. 4a² − 1/(4a²) = 3√13
ii. (2a + 1/(2a))² = 13
iii. 4a² + 1/(4a²) = 11
নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', 'a + 1/a = 0 হলে, √2(√a + 1/√a) এর মান কত?', 'mcq', '{"ক":"","খ":"1","গ":"2","ঘ":"4"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'ছাপায় ক অপশনটি অনুপস্থিত — শুধু খ) 1, গ) 2, ঘ) 4 ছাপা হয়েছে; ক খালি রাখা হয়েছে, আন্দাজে বসানো হয়নি।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p9', '0.00000538 এর সাধারণ লগের পূর্ণক কত?', 'mcq', '{"ক":"6̅","খ":"5̅","গ":"5","ঘ":"6"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'প্রশ্ন পৃষ্ঠা ৯-এ, অপশনগুলো পৃষ্ঠা ১০-এ ছাপা; ক ও খ অপশনের সংখ্যার উপরে বার (ঋণাত্মক পূর্ণক) আছে।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', '√(2x − 2) + 4 = 5 এর সমাধান সেট নিচের কোনটি?', 'mcq', '{"ক":"{0}","খ":"{}","গ":"{3/2}","ঘ":"{1}"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'কোনো বর্গের বাহুর দৈর্ঘ্য 10% হ্রাস পেলে এর ক্ষেত্রফল শতকরা কত হ্রাস পাবে?', 'mcq', '{"ক":"10%","খ":"19%","গ":"21%","ঘ":"30%"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', '2x + y = 8 এবং 3x − 2y = 5 সমীকরণদ্বয়ের ছেদ বিন্দুর স্থানাঙ্ক কোনটি?', 'mcq', '{"ক":"(-3, 2)","খ":"(-2, 3)","গ":"(2, 3)","ঘ":"(3, 2)"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'দুইটি বৃত্ত পরস্পরকে ছেদ করলে তাদের মধ্যে সর্বোচ্চ কয়টি সাধারণ স্পর্শক অঙ্কন করা সম্ভব?', 'mcq', '{"ক":"1 টি","খ":"2 টি","গ":"3 টি","ঘ":"4 টি"}'::jsonb, 'খ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'M = {2, 3, 4}, N = {2, 4, 7} হলে, M\N = কত?', 'mcq', '{"ক":"{3}","খ":"{7}","গ":"{2, 4}","ঘ":"{3, 7}"}'::jsonb, 'ক', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', '2+x+y+z+162 গুণোত্তর ধারাটির চতুর্থ পদ কোনটি?', 'mcq', '{"ক":"18","খ":"27","গ":"54","ঘ":"81"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'ছাপায় ধারাটি ''2+x+y+z+162'' আকারে; পদগুলো 2, x, y, z, 162 ধরে নেওয়া হয়েছে (প্লাস চিহ্নগুলো পদ পৃথক করেছে বলে মনে হয়) — মূল ছাপা হুবহু রাখা হয়েছে।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'ΔPQR এর ∠Q ও ∠R এর সমদ্বিখণ্ডকদ্বয় বিন্দুতে মিলিত হয়েছে। ∠P = 50° হলে, ∠QOR = কত?', 'mcq', '{"ক":"40°","খ":"65°","গ":"115°","ঘ":"130°"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', 'ছাপায় মিলনবিন্দুর নাম অনুপস্থিত (''বিন্দুতে মিলিত হয়েছে''); ∠QOR থেকে বিন্দুটি O বলে বোঝা যায়।', null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'সমবাহু ত্রিভুজের একটি বাহুকে উভয় দিকে বর্ধিত করলে যে বহিঃস্থ কোণদ্বয় উৎপন্ন হয়, তাদের সমষ্টি কত?', 'mcq', '{"ক":"120°","খ":"180°","গ":"240°","ঘ":"270°"}'::jsonb, 'গ', null, 1, false, 'math-board-dinajpur-2024-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2024, null),
  ('math-board-dinajpur-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p10', 'cot θ = √3 হলে,
