  ('math-board-sylhet-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p20', 'একটি ত্রিভুজের তিনটি বাহুর দৈর্ঘ্য ও সে.মি., 4 সে.মি. এবং 5 সে.মি. হলে এর পরিবৃত্তের কেন্দ্র কোথায় অবস্থিত?', 'mcq', '{"ক":"অতিভুজের উপর","খ":"লম্বের উপর","গ":"ত্রিভুজের অভ্যন্তরে","ঘ":"ত্রিভুজের বহির্ভাগে"}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'ছাপায় প্রথম বাহুর মানের জায়গায় ''ও'' অক্ষর ছাপা (সংখ্যা নয়) — 300 dpi ছবিতে যাচাই করা হয়েছে; ৩-৪-৫ সমকোণী ত্রিভুজ ও ছাপা উত্তর (ক, অতিভুজের উপর) থেকে ৩ হওয়ার কথা মনে হলেও ছাপা অনুযায়ী ''ও'' রাখা হয়েছে, মান আন্দাজে বসানো হয়নি।', null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p20', '√(5/80) কোন ধরনের সংখ্যা?', 'mcq', '{"ক":"স্বাভাবিক","খ":"অমূলদ","গ":"মূলদ","ঘ":"মৌলিক"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p20', 'একটি ক্রমিক সমানুপাতীর প্রান্তীয় রাশি দুইটি 4 এবং 16 হলে এর মধ্য সমানুপাতী কত?', 'mcq', '{"ক":"6","খ":"8","গ":"10","ঘ":"12"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
