  ('math-board-sylhet-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'অবনতি কোণের মান কত ডিগ্রি হলে একটি মিনারের দৈর্ঘ্য এবং ছায়ার দৈর্ঘ্য সমান হবে?', 'mcq', '{"ক":"90°","খ":"60°","গ":"45°","ঘ":"30°"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'একটি গাছের উচ্চতা 2√3 মিটার। গাছের গোড়া হতে 6 মিটার দূরে উন্নতি কোণ কত?', 'mcq', '{"ক":"15°","খ":"30°","গ":"45°","ঘ":"60°"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', '(5×3^{x+1} − 14×3^x)/3^x এর মান কত?', 'mcq', '{"ক":"2","খ":"1","গ":"-1","ঘ":"-2"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'ছাপায় গুণের চিহ্ন বিন্দু দিয়ে (5.3^{x+1} − 14.3^x) এবং ভগ্নাংশটি 3^x দিয়ে ভাগ আকারে আছে; দৃশ্য যাচাই করা হয়েছে।', null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'নিচের কোনটি অমূলদ সংখ্যা?', 'mcq', '{"ক":"0.5̇3̇","খ":"0.80","গ":"√8","ঘ":"√9"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'ক অপশনে আবৃত্ত বিন্দু 5 ও 3 উভয়ের উপরে (0.5̇3̇); ছাপা থেকে যাচাই করা হয়েছে।', null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'x = √6, y = √3 হলে (x - y)²+2xy এর মান কত?', 'mcq', '{"ক":"3","খ":"√18","গ":"2√18","ঘ":"9"}'::jsonb, 'ঘ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'f(x) = x⁴ − 7x³ − 5 হলে f(−1) = কত?', 'mcq', '{"ক":"3","খ":"1","গ":"-11","ঘ":"-13"}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'a + b = √3, a − b = 1 হলে 4ab এর মান নিচের কোনটি?', 'mcq', '{"ক":"4","খ":"√3 + 1","গ":"2","ঘ":"√3 − 1"}'::jsonb, 'গ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'Q = {1, a} হলে P(Q) নিচের কোনটি?', 'mcq', '{"ক":"{1, a}","খ":"{1}, {a}, {1, a}","গ":"{1}, {a}, {1, a}, ∅","ঘ":"{{1}, {a}, {1, a}, ∅}"}'::jsonb, 'ঘ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', '64/(64)^x = 16 হলে x এর মান কত?', 'mcq', '{"ক":"4","খ":"1/3","গ":"−1/3","ঘ":"-4"}'::jsonb, 'খ', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'ছাপায় 64 লব ও (64)^x হর আকারে ভগ্নাংশ হিসেবে আছে; দৃশ্য যাচাই করা হয়েছে।', null, 'sylhet', 2024, null),
  ('math-board-sylhet-2024-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p21', 'PN চাপের দৈর্ঘ্য কত?', 'mcq', '{"ক":"3.14 সে.মি.","খ":"6.28 সে.মি.","গ":"12.57 সে.মি.","ঘ":"40.84 সে.মি."}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে MN ব্যাস, OP ব্যাসার্ধ, ∠PON = 60° দেখা যায়; চাপের দৈর্ঘ্য বের করতে এই কোণ ও ব্যাসার্ধ (MN = 6 সে.মি. থেকে r = 3 সে.মি.) প্রয়োজন।', 'চিত্রে O কেন্দ্রবিশিষ্ট বৃত্তে MN একটি ব্যাস (M নিচে, N উপরে), OP ডানদিকে ব্যাসার্ধ এবং ∠PON = 60°। O কেন্দ্রবিশিষ্ট বৃত্তে MN = 6 সে.মি.', 'sylhet', 2024, 'diagram'),
  ('math-board-sylhet-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', 'বৃত্তকলা PON এর ক্ষেত্রফল কত?', 'mcq', '{"ক":"4.71 বর্গ সে.মি.","খ":"9.42 বর্গ সে.মি.","গ":"18.85 বর্গ সে.মি.","ঘ":"40.84 বর্গ সে.মি."}'::jsonb, 'ক', null, 1, false, 'math-board-sylhet-2024-mcq', false, null, 'board-mcq', 'চিত্র-নির্ভর: চিত্রে MN ব্যাস, OP ব্যাসার্ধ, ∠PON = 60° দেখা যায়; বৃত্তকলার ক্ষেত্রফল বের করতে এই কোণ ও ব্যাসার্ধ (MN = 6 সে.মি. থেকে r = 3 সে.মি.) প্রয়োজন।', 'চিত্রে O কেন্দ্রবিশিষ্ট বৃত্তে MN একটি ব্যাস (M নিচে, N উপরে), OP ডানদিকে ব্যাসার্ধ এবং ∠PON = 60°। O কেন্দ্রবিশিষ্ট বৃত্তে MN = 6 সে.মি.', 'sylhet', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', 'OA = 5 সেন্টিমিটার হলে PA এর দৈর্ঘ্য কত সেন্টিমিটার?', 'mcq', '{"ক":"9","খ":"10","গ":"12","ঘ":"15"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: O কেন্দ্রবিশিষ্ট বৃত্ত, বহিঃস্থ বিন্দু P থেকে PA ও PB দুটি স্পর্শক (A, B স্পর্শবিন্দু), OP = 13 সে.মি.।', 'নিচের চিত্রের আলোকে প্রশ্নের উত্তর দাও: OP = 13 সেন্টিমিটার, ∠OPB = 30°', 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', '△OBP এর ক্ষেত্রফল কত?', 'mcq', '{"ক":"30 সেন্টিমিটার","খ":"40 সেন্টিমিটার","গ":"30 বর্গ সেন্টিমিটার","ঘ":"40 বর্গ সেন্টিমিটার"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: O কেন্দ্রবিশিষ্ট বৃত্ত, বহিঃস্থ বিন্দু P থেকে PA ও PB দুটি স্পর্শক (A, B স্পর্শবিন্দু), OP = 13 সে.মি.।', 'নিচের চিত্রের আলোকে প্রশ্নের উত্তর দাও: OP = 13 সেন্টিমিটার, ∠OPB = 30°', 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', '∠A এর মান কোনটি?', 'mcq', '{"ক":"90°","খ":"60°","গ":"45°","ঘ":"30°"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ ABC, B-তে সমকোণ, অতিভুজ AC = 2, BC = √3।', 'নিচের চিত্রের প্রেক্ষিতে প্রশ্নের উত্তর দাও:', 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', '△ABC-এ i. cosA = sinC ii. cosC+secA = 5/2 iii. tanC = 1/√3 উপরের তথ্য অনুসারে কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ ABC, B-তে সমকোণ, অতিভুজ AC = 2, BC = √3। ii-তে ছাপা ''cosC+secA = 5/2'' (C/t অক্ষর অস্পষ্ট); চিত্রের মান অনুযায়ী cosC+secA = 2+√3/2 ≠ 5/2 — ছাপা চাবি d (i, ii ও iii) অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', 'নিচের চিত্রের প্রেক্ষিতে প্রশ্নের উত্তর দাও:', 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p22', 'x ও y অক্ষ হতে যথাক্রমে 3 ও 4 একক দূরে অবস্থিত যে বিন্দুটি ৩য় চতুর্ভাগে অবস্থিত তার স্থানাংক কত?', 'mcq', '{"ক":"(3,4)","খ":"(3,-4)","গ":"(-3,4)","ঘ":"(-3,-4)"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', '1/a = 3+2√2 হলে a − 1/a এর মান কত?', 'mcq', '{"ক":"−4√2","খ":"-4","গ":"0","ঘ":"4√2"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', 'x²−√2x+1 = 0 হলে i. x+1/x = √2 ii. x²+1/x² = 0 iii. x³+1/x³ = −√2 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', '(3⁻¹ ÷ 9⁻¹)⁻¹ এর মান কত?', 'mcq', '{"ক":"3","খ":"3⁰","গ":"3⁻¹","ঘ":"3⁻²"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', '0.000567 এর সাধারণ লগের পূর্ণক নিচের কোনটি?', 'mcq', '{"ক":"7","খ":"6̄","গ":"5̄","ঘ":"4̄"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', 'x²−x−12 = 0 সমীকরণের i. একটি উৎপাদক x+3 ii. ঘাত 2 iii. একটি বীজ 4 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p23', '(x²−3)² = 0 সমীকরণের মূল কয়টি?', 'mcq', '{"ক":"4","খ":"3","গ":"2","ঘ":"1"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'ছাপা চাবি d (1); সমীকরণের বীজ ±√3 (দুটি পৃথক বীজ) — সোর্সের ব্যাখ্যায় ''মূলের সংখ্যা একই'' বলে 1 ধরা হয়েছে; অডিটে নিষ্পত্তি আবশ্যক।', null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', '(3m+n)/(n−m) = 9 হলে m:n কত হবে?', 'mcq', '{"ক":"3:2","খ":"2:3","গ":"1:3","ঘ":"3:1"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', 'নিচের চিত্রটির মোট কতটি প্রতিসাম্য রেখা আছে?', 'mcq', '{"ক":"8","খ":"6","গ":"4","ঘ":"2"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: ''+'' আকৃতির চিত্র (দুটি পরস্পর লম্ব আয়তক্ষেত্রের ছেদ); প্রতিসাম্য রেখা 4টি।', null, 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', 'H অক্ষরটির ঘূর্ণন প্রতিসাম্য কোণ কত?', 'mcq', '{"ক":"60°","খ":"90°","গ":"180°","ঘ":"360°"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', 'p, q, r ক্রমিক সমানুপাতি হলে— i. p/q = q/r ii. pq = qr iii. q² = pr নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', '128+64+32+...... ধারাটির কততম পদ 1/2?', 'mcq', '{"ক":"9তম","খ":"8তম","গ":"7তম","ঘ":"6তম"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', '2+a+b+c+162 গুণোত্তর ধারাভুক্ত হলে, সাধারণ অনুপাত কত?', 'mcq', '{"ক":"6","খ":"3","গ":"1/3","ঘ":"1/6"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', 'সূর্যের উন্নতি কোণ 90° হলে, কোনো গাছের ছায়ার দৈর্ঘ্য কত মিটার?', 'mcq', '{"ক":"0 মিটার","খ":"30 মিটার","গ":"45 মিটার","ঘ":"90 মিটার"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p24', 'চিত্রে AC = CD হলে AB এর দৈর্ঘ্য কত?', 'mcq', '{"ক":"20 মিটার","খ":"10√2 মিটার","গ":"30 মিটার","ঘ":"30√2 মিটার"}'::jsonb, 'গ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ DBC (B-তে সমকোণ), ∠DCB = 60°, BC = 10 মি.; C বিন্দু AB রেখার উপর, A C-এর উপরে বর্ধিতাংশে (ড্যাশ রেখা)।', null, 'chattogram', 2024, 'diagram'),
  ('math-board-chattogram-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', '3x−5y−7 = 0 এবং 6x−10y−15 = 0 সমীকরণ জোটটি— i. অসামঞ্জস ii. একটি মাত্র সমাধান আছে iii. পরস্পর অনির্ভরশীল নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', '2x−y = 8 এবং x−2y = 4 হলে xy এর মান কত?', 'mcq', '{"ক":"32","খ":"16","গ":"4","ঘ":""}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'ঘ অপশন ছাপায় অনুপস্থিত; সমীকরণ থেকে x = 4, y = 0, xy = 0 — তবে মান ছাপায় নেই বলে অপশন খালি রাখা হলো, গণনা করে বসানো হয়নি। ছাপা চাবি ঘ।', null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'একটি আয়তক্ষেত্রের দৈর্ঘ্য প্রস্থ অপেক্ষা 3 মিটার বেশি এবং পরিসীমা 30 মি হলে আয়তক্ষেত্রের প্রস্থ কত মিটার?', 'mcq', '{"ক":"6","খ":"9","গ":"18","ঘ":"36"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'পরীক্ষার নম্বর ও জনসংখ্যা কোন ধরনের চলক', 'mcq', '{"ক":"বিচ্ছিন্ন চলক","খ":"অবিচ্ছিন্ন চলক","গ":"বাস্তব চলক","ঘ":"অবিন্যস্ত চলক"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', '1−1+1−1+...... ধারাটির— i. 2n+1 সংখ্যক পদের সমষ্টি 1. ii. (2n+2)তম পদ = −1 iii. পদসংখ্যা অসীম নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'x²−5x²+1 = 0 হলে x+1/x এর মান কত?', 'mcq', '{"ক":"7","খ":"3","গ":"√7","ঘ":"√3"}'::jsonb, 'ঘ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'ছাপা সমীকরণ x²−5x²+1 = 0 হলে x+1/x = ±5/2, যা অপশনে নেই; x⁴−5x²+1 = 0 ও x−1/x ধরলে √3 (ঘ) মেলে — ছাপায় ঘাত/চিহ্ন ভুল থাকতে পারে; ছাপা চাবি d অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'f(y) = (1+y²+y³)/y² হলে f(−1/2) এর মান কত?', 'mcq', '{"ক":"9/32","খ":"9/2","গ":"5","ঘ":"20"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'নিচের কোনটি ফাঁকা সেট?', 'mcq', '{"ক":"{x∈N: x মৌলিক সংখ্যা, 23 …}","খ":"{x∈N: x মৌলিক সংখ্যা, 11 < x < 19}","গ":"{x∈N: 23 …}","ঘ":"{x∈Z: 11 …}"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', 'ক, গ, ঘ অপশন ছাপায় মাঝপথে কাটা (ডানদিক ছাঁটা); খ সম্পূর্ণ: {x∈N: x মৌলিক সংখ্যা, 11 < x < 19}। ছাপা চাবি a অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'প্রচুরক শ্রেণির মধ্যমান কত?', 'mcq', '{"ক":"45.5","খ":"55.5","গ":"65.5","ঘ":"75.5"}'::jsonb, 'খ', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, 'নিচের উদ্দীপক থেকে প্রশ্নের উত্তর দাও: শ্রেণি: 31-40, 41-50, 51-60, 61-70, 71-80; গণসংখ্যা: 5, 8, 12, 9, 6।', 'chattogram', 2024, null),
  ('math-board-chattogram-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p25', 'মধ্যক নির্ণয়ের ক্ষেত্রে— i. n/2 = 20 ii. f_m = 12 iii. F_c = 25 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'math-board-chattogram-2024-mcq', false, null, 'board-mcq', null, 'নিচের উদ্দীপক থেকে প্রশ্নের উত্তর দাও: শ্রেণি: 31-40, 41-50, 51-60, 61-70, 71-80; গণসংখ্যা: 5, 8, 12, 9, 6।', 'chattogram', 2024, null),
  ('math-board-rajshahi-2024-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', 'x/y = 1 হলে, θ = কত?', 'mcq', '{"ক":"30°","খ":"45°","গ":"60°","ঘ":"90°"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে প্রশ্নের উত্তর দাও: sinθ/x = cosθ/y', 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', 'sinθ = কত?', 'mcq', '{"ক":"x/√(x²+y²)","খ":"y/√(x²+y²)","গ":"x/√(x²−y²)","ঘ":"y/√(x²−y²)"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে প্রশ্নের উত্তর দাও: sinθ/x = cosθ/y', 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', 'AB² = কোনটি?', 'mcq', '{"ক":"AC²−BC²","খ":"AC²+BC²","গ":"BC²−AC²","ঘ":"BC²+AC²"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ ABC (B-তে সমকোণ), BC বাহুকে D পর্যন্ত বর্ধিত; ∠ACD বহিঃস্থ কোণ।', 'নিচের চিত্রের আলোকে প্রশ্নের উত্তর দাও:', 'rajshahi', 2024, 'diagram'),
  ('math-board-rajshahi-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', '∠ACD = কোনটি?', 'mcq', '{"ক":"∠CBA+∠BCD","খ":"∠BAC+∠ACB","গ":"∠ABC+∠BAC","ঘ":"∠ABC+∠ACB"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ ABC (B-তে সমকোণ), BC বাহুকে D পর্যন্ত বর্ধিত; ∠ACD বহিঃস্থ কোণ।', 'নিচের চিত্রের আলোকে প্রশ্নের উত্তর দাও:', 'rajshahi', 2024, 'diagram'),
  ('math-board-rajshahi-2024-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', '(a − 1/a)² এর মান কত?', 'mcq', '{"ক":"14","খ":"12","গ":"6","ঘ":"4"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, 'নিচের তথ্যের আলোকে প্রশ্নের উত্তর দাও: a + 1/a = 4', 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', '(a³ + 1/a³) = কত?', 'mcq', '{"ক":"","খ":"24","গ":"52","ঘ":"76"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ক অপশন ছাপায় অনুপস্থিত।', 'নিচের তথ্যের আলোকে প্রশ্নের উত্তর দাও: a + 1/a = 4', 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', 'ū = −2, x̄ = 12 এবং h = 4 হলে, অনুমিত গড় a = কত?', 'mcq', '{"ক":"20","খ":"10","গ":"6","ঘ":"4"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ছাপায় ū, x̄-এর বার (bar) ''₂'' সাবস্ক্রিপ্টের মতো দেখায় (u₂, x₂ ছাপা); a = x̄ − hū = 12 − 4×(−2) = 20।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p26', 'একটি আয়তক্ষেত্রের ঘূর্ণন কোণের পরিমাণ কত?', 'mcq', '{"ক":"360°","খ":"180°","গ":"90°","ঘ":"45°"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'ABCD বৃত্তে অন্তর্লিখিত চতুর্ভুজের ∠ABC = 110° হলে, ∠ADC = কত?', 'mcq', '{"ক":"250°","খ":"110°","গ":"70°","ঘ":"60°"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'কোনো শ্রেণির নিম্নসীমা 30 এবং শ্রেণিমধ্যমান 32 হলে, ওই শ্রেণির ঊর্ধ্বসীমা কত?', 'mcq', '{"ক":"37","খ":"35","গ":"34","ঘ":"33"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'সমকোণী ত্রিভুজের ক্ষেত্রে পরিকেন্দ্র ত্রিভুজের কোথায় অবস্থিত?', 'mcq', '{"ক":"অভ্যন্তরে","খ":"বহির্ভাগে","গ":"অতিভুজের উপর","ঘ":"লম্বের উপর"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'tan(θ−45°) = √3 হলে, θ = এর মান কত?', 'mcq', '{"ক":"15°","খ":"60°","গ":"75°","ঘ":"105°"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'একটি রম্বস আঁকতে কতটি উপাত্ত প্রয়োজন?', 'mcq', '{"ক":"2টি","খ":"3টি","গ":"4টি","ঘ":"5টি"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'একটি ত্রিভুজের তিনটি কোণের অনুপাত 2:3:5 হলে, বৃহত্তম কোণটি ক্ষুদ্রতম কোণটির কতগুণ?', 'mcq', '{"ক":"5/2 গুণ","খ":"5/3 গুণ","গ":"3/5 গুণ","ঘ":"2/5 গুণ"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'a/2 = b/2 = c/2 হলে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"a:b:c = 2:3:4","খ":"a:b:c = 4:3:2","গ":"a:b:c = 8:9:6","ঘ":"a:b:c = 6:8:9"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ছাপায় তিনটি হরই 2 (a/2 = b/2 = c/2); হর 2, 3, 4 হলে a:b:c = 2:3:4 (ক) মেলে — ছাপায় হর ভুল, ছাপা চাবি a অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', '3 সে.মি. ধারবিশিষ্ট ঘনকের— i. আয়তন 27 ঘন সে.মি. ii. কর্ণের দৈর্ঘ্য 3√3 সে.মি. iii. সম্পূর্ণ তলের ক্ষেত্রফল ১ বর্গ সে.মি. নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'iii-তে ছাপা ''১ বর্গ সে.মি.''; ৩ সে.মি. ধারের ঘনকের সম্পূর্ণ তলের ক্ষেত্রফল ৫৪ বর্গ সে.মি. হওয়ার কথা — ছাপায় সংখ্যা ভুল/কাটা; ছাপা চাবি d অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', '2x+3y = −4 এবং x = 1 হলে, y = কত?', 'mcq', '{"ক":"4","খ":"−1","গ":"−2","ঘ":"−4"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'চিত্রে, ABCD একটি আয়ত হলে, △ADE এর ক্ষেত্রফল কোনটির সমান।', 'mcq', '{"ক":"□ABCD এর ক্ষেত্রফল","খ":"△ABFD এর ক্ষেত্রফল","গ":"△CDF এর ক্ষেত্রফল","ঘ":"△BEF এর ক্ষেত্রফল"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'চিত্র: আয়তক্ষেত্র ABCD (A নিচে-বামে, B নিচে-মাঝে, C উপরে-মাঝে, D উপরে-বামে), AB-কে B ছাড়িয়ে E পর্যন্ত বর্ধিত (AB = BE চিহ্নিত), DE কর্ণ BC-কে F বিন্দুতে ছেদ করে।', null, 'rajshahi', 2024, 'diagram'),
  ('math-board-rajshahi-2024-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', 'একটি দ্রব্যের ক্রয়মূল্য : বিক্রয়মূল্য = 5:6 হলে শতকরা লাভ কত?', 'mcq', '{"ক":"20%","খ":"25%","গ":"30%","ঘ":"40%"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', '6+12+24+...... ধারাটির অষ্টম পদ কত?', 'mcq', '{"ক":"84","খ":"252","গ":"768","ঘ":"1536"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p27', '2.34̇ এর সাধারণ ভগ্নাংশ কোনটি?', 'mcq', '{"ক":"211/900","খ":"211/90","গ":"231/90","ঘ":"234/9"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'আবৃত্ত দশমিকের বিন্দুটি ছাপায় অস্পষ্ট; চাবি 211/90 অনুযায়ী 4-এর উপরে আবৃত্ত-বিন্দু (2.34̇) ধরা হয়েছে।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'log_z(²√3 − √3) এর মান কোনটি?', 'mcq', '{"ক":"1/6","খ":"1/5","গ":"5/6","ঘ":"6/5"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ছাপা অনুযায়ী ²√3 − √3 = 0 এবং ভিত্তি z অসংজ্ঞায়িত — প্রশ্নটি ছাপায় ত্রুটিপূর্ণ; ছাপা চাবি c (5/6) অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', '4x³+3x²−2x+1 = 0 সমীকরণের ঘাত কত?', 'mcq', '{"ক":"4","খ":"3","গ":"2","ঘ":"1"}'::jsonb, 'খ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', '125 এর— i. সাধারণ লগের পূর্ণক 2 ii. সাধারণ লগের অংশক .09691 iii. 5 ভিত্তিক লগ 3 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'প্রশ্নের মূল অংশ ছাপায় কাটা (''125 এর -'' পর্যন্ত); প্রসঙ্গ থেকে 125-এর সাধারণ লগ সংক্রান্ত বলে ধরা হয়েছে।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'x² = 2x সমীকরণের সমাধান সেট কোনটি?', 'mcq', '{"ক":"{}","খ":"{0}","গ":"{2}","ঘ":"{0, 2}"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ঘ অপশনে ছাপায় ''{0.2}'' (কমা অনুপস্থিত); সমাধান সেট {0, 2} অনুযায়ী লেখা হয়েছে।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'X = {a, b, c}, Y = {b} এবং Z = X\Y হলে P(Z) এর উপাদান কয়টি?', 'mcq', '{"ক":"১টি","খ":"২টি","গ":"3টি","ঘ":"4টি"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-027', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'দুইটি সংখ্যার অনুপাত 4:5 এবং এদের ল.সা.গু. 120 হলে, বৃহত্তম সংখ্যাটি কত?', 'mcq', '{"ক":"20","খ":"24","গ":"30","ঘ":"120"}'::jsonb, 'গ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-028', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'ABD বৃত্তের কেন্দ্র O হলে,— i. C, AB এর মধ্যবিন্দু ii. ∠OAC = ∠OBC iii. ∠OAC = ∠OBC = এক সমকোণ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'চিত্র ছাপায় অনুপস্থিত; উদ্দীপক ''ABD বৃত্তের কেন্দ্র O হলে'' ভাঙা — চিত্র ছাড়া i–iii যাচাই করা যায়নি; iii-তে ছাপা ''∠OAC = ∠OBC এক সমকোণ'' হুবহু রাখা হয়েছে; ছাপা চাবি a অনুযায়ী রাখা হয়েছে।', null, 'rajshahi', 2024, 'diagram'),
  ('math-board-rajshahi-2024-mcq-029', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'নিচের কোনটি {x∈N: x মৌলিক সংখ্যা এবং 2≤x≤7} সেটটিকে তালিকা পদ্ধতিতে প্রকাশ করে?', 'mcq', '{"ক":"{2,3,7}","খ":"{2,3,7}","গ":"{3,5,7}","ঘ":"{2,3,5,7}"}'::jsonb, 'ঘ', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'ক ও খ ছাপায় একই ({2,3,7}); ঘ-তে ছাপায় ''(2.3, 5, 7}'' (বন্ধনী/কমা ভুল) — সঠিক সেট {2,3,5,7} অনুযায়ী লেখা হয়েছে।', null, 'rajshahi', 2024, null),
  ('math-board-rajshahi-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p28', 'চিত্রে sin B = কত?', 'mcq', '{"ক":"2/√13","খ":"3/√13","গ":"√13/3","ঘ":"√13/2"}'::jsonb, 'ক', null, 1, false, 'math-board-rajshahi-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ, A-তে সমকোণ, AC = 2, AB = 3, অতিভুজ BC = √13; B কোণে sin B = 2/√13।', null, 'rajshahi', 2024, 'diagram'),
  ('math-board-dhaka-2024-mcq-001', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'ত্রিভুজের ক্ষেত্রে— i. দুটি ত্রিভুজ সদৃশকোণী হলে তাদের অনুরূপ বাহুগুলোর অনুপাত সমান হবে ii. দুইটি ত্রিভুজ সদৃশকোণী এবং এদের একজোড়া অনুরূপ বাহু সমান হলে ত্রিভুজদ্বয় সর্বসম iii. তিনটি কোণ দিয়ে অংকিত ত্রিভুজকে সদৃশ ত্রিভুজ বলা হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-002', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'log_(2√2) 64 এর মান নিচের কোনটি', 'mcq', '{"ক":"1/4","খ":"1","গ":"4","ঘ":"2√2"}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-003', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'x²+y² = 4xy হলে, x²/y² + y²/x² এর মান কত?', 'mcq', '{"ক":"4","খ":"14","গ":"18","ঘ":"20"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-004', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', '√(3x−6)+5 = 2 সমীকরণটির সমাধান সেট কোনটি?', 'mcq', '{"ক":"∅","খ":"{−5}","গ":"{−3}","ঘ":"{5}"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-005', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'একটি ত্রিভুজের তিনটি বাহুর দৈর্ঘ্য দেওয়া আছে। নিচের কোন ক্ষেত্রে সমকোণী ত্রিভুজ গঠন করা সম্ভব?', 'mcq', '{"ক":"2 সে.মি., 3 সে.মি., 4 সে.মি.","খ":"3 সে.মি., 5 সে.মি., 7 সে.মি.","গ":"5 সে.মি., 12 সে.মি., 13 সে.মি.","ঘ":"10 সে.মি., 15 সে.মি., 20 সে.মি."}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-006', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'যদি tan A = 4/3 হয়, তাহলে √((1−sin²A)/sin²A) = কত?', 'mcq', '{"ক":"3/4","খ":"4/5","গ":"5/4","ঘ":"5/3"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-007', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'চিত্রে BC || DE, AE = CE এবং AB = 8 cm, BC = 6 cm হলে— i. DE = 3 cm ii. AD = 4 cm iii. △ABC ও △ADE সদৃশ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', 'চিত্র: ত্রিভুজ ABC, শীর্ষ A, D AB-র উপর, E AC-র উপর, DE || BC; AE = CE (E, AC-র মধ্যবিন্দু)।', null, 'dhaka', 2024, 'diagram'),
  ('math-board-dhaka-2024-mcq-008', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'sinθ = √3/2 হলে, cotθ = ?', 'mcq', '{"ক":"1/√3","খ":"1/√2","গ":"√3/2","ঘ":"√3"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-009', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'f(x) = x³ − x − 24 হলে, x এর কোন মানের জন্য f(x) = 0 হবে?', 'mcq', '{"ক":"2","খ":"3","গ":"4","ঘ":"6"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-010', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p29', 'A = {1, 2, 3, 4} হলে, সেট A এর প্রকৃত উপসেট কয়টি?', 'mcq', '{"ক":"4","খ":"14","গ":"15","ঘ":"16"}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-011', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'চিত্র হতে sinθ secθ এর মান কত?', 'mcq', '{"ক":"√3/4","খ":"1/√3","গ":"2/√3","ঘ":"√3"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', 'চিত্র: সমকোণী ত্রিভুজ PQR, Q-তে সমকোণ, PQ = √3, QR = 1, PR = 2, R-তে কোণ θ।', null, 'dhaka', 2024, 'diagram'),
  ('math-board-dhaka-2024-mcq-012', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'যদি secA + tanA = √5 হয়, তবে sinA = কত?', 'mcq', '{"ক":"√5","খ":"3/2","গ":"2/3","ঘ":"1/√5"}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-013', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'অর্ধবৃত্ত অপেক্ষা ছোট চাপে অন্তর্লিখিত কোণ—', 'mcq', '{"ক":"সমকোণ","খ":"পূরককোণ","গ":"সূক্ষ্মকোণ","ঘ":"স্থূলকোণ"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-014', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', '144 এর 2√3 ভিত্তিক log কত?', 'mcq', '{"ক":"√3","খ":"2","গ":"2√3","ঘ":"4"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-015', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'সুষম পঞ্চভুজের শীর্ষ বিন্দুতে উৎপন্ন কোণের পরিমাণ কত?', 'mcq', '{"ক":"108°","খ":"110°","গ":"120°","ঘ":"144°"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-016', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', '2x + y = 3 এবং 4x + 2y = 6 সমীকরণদ্বয়— i. পরস্পর নির্ভরশীল ii. পরস্পর সমঞ্জস iii. অসংখ্য সমাধান আছে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-017', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', '0.3̇ × 0.6̇ = কত?', 'mcq', '{"ক":"1","খ":"0.2̇","গ":"0.1̇8̇","ঘ":"0.18̇"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-018', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'a + b = √16 এবং ab = 1 হলে, (a − b)² = কত?', 'mcq', '{"ক":"12","খ":"14","গ":"22","ঘ":"24"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-019', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', '1/4^(−x) = 64 হলে, x = কত?', 'mcq', '{"ক":"6","খ":"3","গ":"−12","ঘ":"−4"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-020', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p30', 'a, b, c ক্রমিক সমানুপাতি হলে— i. b² = ac ii. 2b = a+c iii. (a+b)/b = (b+c)/c নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-021', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', '64+32+16+8+.......... ধারার ৮ম পদ কত?', 'mcq', '{"ক":"1/2","খ":"1/4","গ":"2","ঘ":"4"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-022', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', 'কোন শর্তে x⁰ = 1?', 'mcq', '{"ক":"x ≠ 0","খ":"x = 0","গ":"x > 0","ঘ":"x < 0"}'::jsonb, 'ক', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-023', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', 'যদি a² − √2a + 1 = 0 হয় তবে— i. a + 1/a = √2 ii. a² + 1/a² = 2 iii. a³ + 1/a³ = √2 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', 'গণিতে a²+1/a² = 0 (ii ভুল) এবং a³+1/a³ = −√2 (iii-তে ''−'' অনুপস্থিত থাকতে পারে); ছাপা বিবৃতি অনুযায়ী শুধু i সঠিক হলেও ছাপা চাবি b (i ও iii) অনুযায়ী রাখা হয়েছে, অডিটে নিষ্পত্তি আবশ্যক।', null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-024', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', '∠BOC এর পূরক কোণ কোনটি?', 'mcq', '{"ক":"∠AOC","খ":"∠DOC","গ":"∠AOD","ঘ":"∠BOD"}'::jsonb, 'খ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', 'চিত্র: AOB সরলরেখা, O-তে OD লম্ব (∠DOB = 90°), OC রশ্মি; ∠BOC-এর পূরক ∠DOC।', null, 'dhaka', 2024, 'diagram'),
  ('math-board-dhaka-2024-mcq-025', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', 'চা ও চিনির অনুপাত 7:3, মিশ্রণে চায়ের পরিমাণ শতকরা কত?', 'mcq', '{"ক":"30%","খ":"40%","গ":"50%","ঘ":"70%"}'::jsonb, 'ঘ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
  ('math-board-dhaka-2024-mcq-026', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p31', 'O কেন্দ্রবিশিষ্ট বৃত্তে ABC একটি সমবাহু ত্রিভুজ এবং ∠BAC এর সমদ্বিখণ্ডক AO হলে ∠AOC = ?', 'mcq', '{"ক":"30°","খ":"60°","গ":"120°","ঘ":"180°"}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2024, null),
