  ('math-board-dhaka-2024-mcq-030', 'class9-math-bn-guide', 'satt-math-board-2023-2024.pdf p32', 'আয়তাকার ঘরের পরিসীমা একটি বেলনের ভূমির ব্যাস হলে, বেলনটির ভূমির ক্ষেত্রফল কত?', 'mcq', '{"ক":"10π বর্গ মি.","খ":"20π বর্গ মি.","গ":"100π বর্গ মি.","ঘ":"400π বর্গ মি."}'::jsonb, 'গ', null, 1, false, 'math-board-dhaka-2024-mcq', false, null, 'board-mcq', null, 'নিচের উদ্দীপকটি পড়ে নিচের প্রশ্নের উত্তর দাও: আয়তাকার ঘরের মেঝের দৈর্ঘ্য, প্রস্থ অপেক্ষা 2 মিটার বেশি এবং মেঝের পরিসীমা 20 মিটার।', 'dhaka', 2024, null),
  ('bn1-board-all-boards-2018-mcq-01', 'class9-bangla-1st-bn-guide', 'সকল বোর্ড ২০১৮', 'উদ্দীপকটি তোমার পাঠ্যবইয়ের কোন রচনাটিকে ইঙ্গিত করছে?', 'mcq', '{"ক":"নিরীহ বাঙালি","খ":"দেনাপাওনা","গ":"অভাগীর স্বর্গ","ঘ":"আম-আঁটির ভেঁঁপু"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2018-mcq', false, null, 'board-mcq', null, 'ভগবানের ফৌজদারি কোট নাই সেখানে জাত বিচার পৈতে টিকিটুপি টোপর সব সেথা ভাই একাক্কাার জাত সে শিকেয় তোলা রবে, কম নিয়ে বিচার হবে, বামুন চাঁড়াাল এক গোয়াালে, নরক কিংংবা স্বর্গে থোওয়াা ।', 'all', 2018, null),
  ('bn1-board-all-boards-2018-mcq-02', 'class9-bangla-1st-bn-guide', 'সকল বোর্ড ২০১৮', 'উক্ত রচনায় প্রকাশ পেয়েছে— i. সামন্তবাদের নিমম রূপ ii. নিম্নবিত্ত মানুষের জীবন iii. শ্রমজীবীদের প্রতি সহানুভূতি নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2018-mcq', false, null, 'board-mcq', null, 'ভগবানের ফৌজদারি কোট নাই সেখানে জাত বিচার পৈতে টিকিটুপি টোপর সব সেথা ভাই একাক্কাার জাত সে শিকেয় তোলা রবে, কম নিয়ে বিচার হবে, বামুন চাঁড়াাল এক গোয়াালে, নরক কিংংবা স্বর্গে থোওয়াা ।', 'all', 2018, null),
  ('bn1-board-all-boards-2018-mcq-03', 'class9-bangla-1st-bn-guide', 'সকল বোর্ড ২০১৮', 'উদ্দীপকের সঙ্গে তোমার পঠিত কোন প্রবের সাদৃশ্য রয়েছে?', 'mcq', '{"ক":"শিক্ষা ও মনুষ্যত্ব","খ":"পয়লা বৈশাখ","গ":"একাত্তরের দিনগুলি","ঘ":"উপেক্ষিত শক্তির উদ্বোধন"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2018-mcq', false, null, 'board-mcq', null, '''গাহি সাম্যের গান- মানুষের চেয়ে বড় কিছু নাই, নহে কিছু মহীয়াান ।', 'all', 2018, null),
  ('bn1-board-all-boards-2018-mcq-04', 'class9-bangla-1st-bn-guide', 'সকল বোর্ড ২০১৮', 'উদ্দীপক ও প্রবের ভাবগত ঐক্য- i. অসাম্প্রদায়িকতায় ii. সাম্যবাদিতায় iii. সত্যবাদিতায় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2018-mcq', false, null, 'board-mcq', null, '''গাহি সাম্যের গান- মানুষের চেয়ে বড় কিছু নাই, নহে কিছু মহীয়াান ।', 'all', 2018, null),
  ('bn1-board-all-boards-2018-mcq-05', 'class9-bangla-1st-bn-guide', 'সকল বোর্ড ২০১৮', 'উদ্দীপকের নামের ধারাবাহিক পরিবতনটির সঙ্গে সম্পকযুক্ত— i. প্রাচীন ভারতীয় আযভাষা > মধ্যভারতীয় আযভাষা > বাংলা ভাষা ii. অবিধবা > অবিহবা > এয়ো iii. মৎস্য > মচ্ছ > মাছ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2018-mcq', false, null, 'board-mcq', null, 'জের পর নানু আদর করে নাতনির নাম দিলেন‘কলি’। মা ডাকেন ‘কালি''। স্কুলে ভর্তি হবার সময় শ্রেণিশিক্ষক নাম দিলেন ''কালিনী'' ।', 'all', 2018, null),
