  ('bn1-board-barishal-2019-mcq-06', 'class9-bangla-1st-bn-guide', 'বরিশাল বোর্ড ২০১৯', 'মতিন মিয়াা অফিসের সব কাজ যথাসময়ে সুন্দরভাবে করেন। বড় অফিসার তার প্রশংসা করলেও তার সহকর্মীরা প্রায়ই তাকে ঠাট্টা-বিদ্রূপ করে। তিনি সবই নীরবে সহ্য করেন, কাউকে কিছু বলেন না। উদ্দীপকের মতিন চরিত্রে প্রকাশিত গুণটি ''মানুষ মুহম্মদ (স.)'' রচনায় যে বাক্যে ফুটে উঠেছে—', 'mcq', '{"ক":"তাঁহাদের পঙক্তিতে আমার স্থান দাও","খ":"এদের জ্ঞান দাও প্রভু, এদের ক্ষমা কর","গ":"আমি রাজা নই, সম্রাাট নই, মানুষের প্রভু নই","ঘ":"আজ তোমরা সবাই স্বাধীন, সবাই মুক্ত"}'::jsonb, 'খ', null, 1, false, 'bn1-board-barishal-2019-mcq', false, null, 'board-mcq', null, null, 'barishal', 2019, null),
  ('bn1-board-barishal-2019-mcq-07', 'class9-bangla-1st-bn-guide', 'বরিশাল বোর্ড ২০১৯', 'কোথায় হাতেম আলির জমিদারি ছিল?', 'mcq', '{"ক":"ডেমরা","খ":"সুনামগঞ্জ","গ":"কদমতলা","ঘ":"রেশমপুর"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-barishal-2019-mcq', false, null, 'board-mcq', null, null, 'barishal', 2019, null),
