  ('bn1-board-barishal-2019-mcq-10', 'class9-bangla-1st-bn-guide', 'বরিশাল বোর্ড ২০১৯', '''খোদার ভেদ বোঝা সত্যিই মুশকিল।''- ''বহিপীর'' নাটকে এ উক্তিটিতে কী প্রকাশ পেয়েছে?', 'mcq', '{"ক":"কৌশল","খ":"মতভেদ","গ":"খোদা ভীরুতা","ঘ":"গূঢ় রহস্য"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-barishal-2019-mcq', false, null, 'board-mcq', null, null, 'barishal', 2019, null),
