  ('bn1-board-sylhet-2019-mcq-02', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', '''সেইদিন এই মাঠ'' কবিতায় কবির মতে কোনটি টিকে থাকবে না?', 'mcq', '{"ক":"নদী","খ":"নক্ষত্র","গ":"সভ্যতা","ঘ":"স্বপ্ন"}'::jsonb, 'গ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
  ('bn1-board-sylhet-2019-mcq-03', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'বুধার যে কথা শুনে চাচির চোখ উজ্জ্বল হয়ে ওঠে— i. যুে যাবার ii. কামাই করার iii. কাকতাড়ুুয়াা সাজার নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
