  ('bn1-board-sylhet-2019-mcq-05', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'রানি বুধাকে কাকতাড়ুুয়াা খেলতে নিষেধ করে, কারণ-', 'mcq', '{"ক":"অসুখ করতে পারে","খ":"রোদে পুড়ে যেতে পারে","গ":"রানির ভালো লাগে না বলে","ঘ":"মিলিটারি গুলি করবে বলে"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
  ('bn1-board-sylhet-2019-mcq-06', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'রুমেল সাহেব শেয়াারবাজারের ব্যবসায় কয়েকবার ক্ষতির সম্মুখীন হন। বিষয়টি পরিবারের কাছে গোপন রেখে ব্যাংাংক ঋণ নিয়ে তিনি পুনরায় ব্যবসায় শুরুর চেষ্টা করেও ব্যথ হন। উদ্দীপকের রুমেল সাহেবের সাথে ‘বহিপীর’ নাটকের যে চরিত্রটি সাদৃশ্যপূণ-', 'mcq', '{"ক":"হাশেম আলি","খ":"হাতেম আলি","গ":"হকিকুল্লাহ","ঘ":"বহিপীর"}'::jsonb, 'খ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
  ('bn1-board-sylhet-2019-mcq-07', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'বিভূতিভূষণ বন্দ্যোপাধ্যাায় কোন উপন্যাাসের জন্য রীবন্দ্র পুরস্কারে ভূষিত হন?', 'mcq', '{"ক":"পথের পাঁচালী","খ":"ইছামতি","গ":"অপরাজিত","ঘ":"আরণ্যক"}'::jsonb, 'খ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
