  ('bn1-board-sylhet-2019-mcq-09', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ২৯ ও ৩০ নং প্রের উত্তর দাও : মি. তারেক লন্ডন থেকে পড়াাশোনা করে এসে সবসময় ইংরেজিতে কথা বলেন। সবাই তাঁকে বাংলায় কথা বলতে বললে তিনি বলেন, বাংলায় কথা বলতে আমার ভালো লাগে না। উদ্দীপকের তারেকের মধ্যে "বঙ্গবাণী'' কবিতার বিষয়বস্তুর কোন দিকটি অনুপিত?', 'mcq', '{"ক":"মাতৃভূমির প্রতি মমতা","খ":"মাতৃভাষার প্রতি মমতা","গ":"মাতৃভাষার প্রতি ঘৃণা","ঘ":"ইংরেজি ভাষার প্রতি ঘৃণ"}'::jsonb, 'খ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
  ('bn1-board-sylhet-2019-mcq-10', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'উদ্দীপকের তারেকের মধ্যে আবদুল হাকিমের কোন উক্তিটি প্রযোজ্য?', 'mcq', '{"ক":"যেই দেশে যেই বাক্য কহে নরগণ; সেই বাক্য বুঝে প্রভু আপে নিরঞ্জন।","খ":"আরবি ফারসি শাস্ত্রে নাই কোনো রা। দেশী ভাষা বুঝিতে ললাটে পুরে ভাগ ।।","গ":"মাতা পিতামহ ক্রমে বঙ্গেত বসতি। দেশী ভাষা উপদেশ মনে হিত অতিঃঃ","ঘ":"দেশী ভাষা বিদ্যাা যার মন ন জুয়াায়। নিজ দেশ তেয়াাগী কেন বিদেশ ন যায় ।"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
