  ('bn1-board-sylhet-2019-mcq-17', 'class9-bangla-1st-bn-guide', 'সিলেট বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ১৭ ও ১৮ নং প্রের উত্তর দাও : জবের মিয়াা দীঘদিন ধরে একটি ঘোড়াা দিয়ে ঘোড়াার পাড়ি চালায়। ঘোড়াাটি এখন বুড়ো হলেও জবের মিয়াা তার যত্ন নেয়। বাড়ির সবাই ঘোড়াাটিকে বিক্রি করতে বললেও চাল কেনার টাকা দিয়ে গম-ভুসি এনে খাওয়াায়। বস্তুত জবের মিয়াা ঘোড়াাটিকে নিজের সন্তানের মতো দেখে । উদ্দীপকের ঘোড়াাটির সাথে নিমগাছ'' গের লক্ষ্মীীবউয়ের সাদৃশ্য করা যায়- i. অবদানে ii. প্রয়োজনীয়তায় iii. পরোপকারে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-sylhet-2019-mcq', false, null, 'board-mcq', null, null, 'sylhet', 2019, null),
