  ('bn1-board-chattogram-2019-mcq-05', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', '"বরিশালের বিখ্যাাত দাশনিক আরজ আলী মাতুব্বর। তিনি পেশায় ছিলেন একজন কৃষক। তাঁর প্রাতিষ্ঠানিক শিক্ষা না থাকলেও তিনি এমন কিছু সাহিত্যকম রেখে গেছেন যা দশনশাের বড় বড় পণ্ডিতরাও পারেননি।” উদ্দীপকের ভাবটি তোমার পঠিত কোন প্রবে পাওয়াা যায়?', 'mcq', '{"ক":"বই পড়াা","খ":"সাহিত্যের রূপ ও রীতি","গ":"শিক্ষা ও মনুষ্যত্ব","ঘ":"পিসাহিত্য"}'::jsonb, 'ক', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
