  ('bn1-board-chattogram-2019-mcq-19', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', '“স্বাধীনতা, এ শব্দটি কীভাবে আমাদের হলো” কবিতায় লোহার শ্রমিকরা কেন এসেছিল?', 'mcq', '{"ক":"মিছিল করতে","খ":"আন্দো লন করতে","গ":"মারপিট করতে","ঘ":"বঙ্গবন্ধুর বক্তব্য শুনতে"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
  ('bn1-board-chattogram-2019-mcq-20', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', 'সে আরেক আবজনা"- ''নিমগাছ'' গে ‘আবজনা’ বলতে গল্পকার কী বোঝাতে চেয়েছেন?', 'mcq', '{"ক":"ময়লা","খ":"কষ্ট","গ":"নোংংরা","ঘ":"জঞ্জাল"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
  ('bn1-board-chattogram-2019-mcq-21', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', 'উপরিউক্ত চরণদ্বয়ের ভাবের সাথে কোন কবিতার। মূলভাবের মিল লক্ষ করা যায়?', 'mcq', '{"ক":"তোমাকে পাওয়াার জন্যে, হে স্বাধীনতা","খ":"স্বাধীনতা, এ শব্দটি কীভাবে আমাদের হলো","গ":"আমি কোনো আগন্তুক ন‍ই","ঘ":"সাহসী জননী বাংলা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, '“ঐ বাম বিধি যে আমারে ধরিতে বাড়াায়ে ছিল রে হাত, মম অগ্নি দহনে জ্বলে পুড়ে তাই বুঁটো সে জগন্নাথ।"', 'chattogram', 2019, null),
