  ('bn1-board-chattogram-2019-mcq-27', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', '“উপেক্ষিত শক্তির উদ্বোধন” প্রবে ছোটলোক সম্প্রদায় আমাদের দেশের কত আনা?', 'mcq', '{"ক":"ছয়জনা","খ":"নয়আনা","গ":"সাতআনা","ঘ":"দশআনা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
  ('bn1-board-chattogram-2019-mcq-28', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', '“চালা হাতুড়ি শাবল চালা"- ''মানুষ'' কবিতার এ চরণে কোন ভাব প্রকাশ পেয়েছে?', 'mcq', '{"ক":"উচ্ছে দ","খ":"বিলোপ","গ":"ধ্বংস","ঘ":"প্রতিরোধ"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
  ('bn1-board-chattogram-2019-mcq-29', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ১৯ ও ২০ নং প্রের উত্তর দাও : গ্রামের প্রভাবশালী ছগির মহাজন আমজাদ আলীর। অল্পবয়সী মেয়েকে বিয়ে করার সকল ব্যবস্থা সম্পন্ন করলে মেয়েটি পালিয়ে গিয়ে বদি মিয়াার বাড়িতে আশ্রয় নেয়। ছগির মহাজন বদি মিয়াাকে বিভিন্ন প্রকার লোভনীয় প্রস্তাব দিলেও তিনি মেয়েটিকে ফেরত দিতে অস্বীকার করেন এবং প্রয়োজনীয় ব্যবস্থা গ্রহণের হুমকি দেন। পরিিতি উপলি করে ছগির মহাজন সবকিছু স্বাভাবিকভাবে মেনে নেয় । উদ্দীপকের ছগির মহাজনের শেষ সিদ্ধান্তটি বহিপীরের কোন চারিত্রিক বৈশিের সাথে সংগতিপূণ?', 'mcq', '{"ক":"লোভ","খ":"কপটতা","গ":"শঠতা","ঘ":"ধূর্তা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
  ('bn1-board-chattogram-2019-mcq-30', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০১৯', 'উদ্দীপকের বদি মিয়াার মনোভাব যে দৃিকোণ থেকে হাতেম আলির সাথে মিল রয়েছে তা হলো- i. মানবিকতা ii. বিচক্ষণতা', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-chattogram-2019-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2019, null),
