  ('bn1-board-cumilla-2019-mcq-06', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ২৬ ও ২৭ নং প্রের উত্তর দাও : ছেলেটার বয়স হবে বছর দশেক পথে ঘরে মানুষ মার খায় দমাদম গাল খায় অজস্র ছাড়াা পেলেই আবার দেয় দৌড় উদ্দীপকের ছেলেটার সাথে ''আম-আঁটির ভেঁঁপু ছোটগে কোনটিতে দুর্গার মিল রয়েছে?', 'mcq', '{"ক":"দূরন্তপনায়","খ":"চতুরতায়","গ":"অবাধ্যতায়","ঘ":"ভবঘুরে স্বভাবে"}'::jsonb, 'ক', null, 1, false, 'bn1-board-cumilla-2019-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2019, null),
