  ('bn1-board-cumilla-2019-mcq-13', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ১৩ ও ১৪ নং প্রের উত্তর দাও : মাঝ উঠানে হঠাৎ বেঁঁকে বসল জমিলা। মজিদের বজ্রমুি হতে নিজের হাত ছাড়িয়ে নেবার চেষ্টা করতে লাগল। হঠাৎ সিধা হয়ে মজিদের মুখে থু থু নিক্ষেপ করল। উদ্দীপকের জমিলার সাথে ‘বহিপীর'' নাটকের সাদৃশ্যপূণ চরিত্র কোনটি?', 'mcq', '{"ক":"খোদেজা","খ":"হাশেম","গ":"তাহেরা","ঘ":"বহিপীর"}'::jsonb, 'গ', null, 1, false, 'bn1-board-cumilla-2019-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2019, null),
