  ('bn1-board-jessore-2019-mcq-08', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', '‘লোহার টুপি কি মানুষের মগজ খায়?''- বুধার এ কথায় প্রকাশ পেয়েছে পাকিস্তানিদের - i. মনুষ্যত্বহীনতা ii. বুিহীনতা iii. অত্যাাচারী মনোভাব নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-09', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ২৩ ও ২৪ নং প্রের উত্তর দাও : বিশিষ্ট শিল্পপতি মিক সাহেব কোরবানির ঈদে বিশাল দুটি গরু কিনে কোরবানি দেন। কিন্তু দরিদ্ররা মাংস চাইতে এলে দারোয়াান তাদের তাড়িয়ে দেয়। বিরাট গেটের বাইরে থেকে তারা বিষণ্ণ দৃিতে তাকিয়ে থাকে। হঠাৎ সেদিকে নজর পড়ে মিক সাহেবের। তিনি দ্রুত দারোয়াানকে নির্দেশ দেন তাদের ভেতরে ঢুকাতে এবং নিজ হাতে তিনি তাদের মাঝে মাংস বিতরণ করেন। উদ্দীপকে দারোয়াানের আচরণ ''মানুষ'' কবিতার কোন চরণের সাথে সাদৃশ্যপূণ?', 'mcq', '{"ক":"দেবতার বরে আজ রাজা-টাজা হয়ে যাবে নিশ্চয়","খ":"গোশত রুটি নিয়াা মসজিদে দিল তালা","গ":"তব মসজিদ মন্দিরে প্রভু নাই মানুষের দাবি","ঘ":"ঐ মন্দির পূজারীর, হায় দেবতা, তোমার নয়"}'::jsonb, 'খ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-10', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'উদ্দীপকের মিক সাহেবের কাজে ''মানুষ'' কবিতার যে প্রত্যাাশার প্রতিফলন ঘটেছে, তা হলো— i. সাম্য প্রতিষ্ঠা ii. শ্রেণিভেদ রোধ iii. বণপ্রথা বিলোপ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
