  ('bn1-board-jessore-2019-mcq-12', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'সবজয়াার চিরন্তন মাতৃরূপের প্রকাশ ঘটে কোন উক্তিতে?', 'mcq', '{"ক":"আজকাল চাষাদের ঘরে লক্ষ্মীী বাঁধা","খ":"ফের দ্যাাখো না এই জ্বরে পড়লো বলে","গ":"ও দুগগা, দেখ তো বাছুরটা হাঁক পাড়ছে কেন?","ঘ":"ইচ্ছে করে একদিকে বেরিয়ে যাই"}'::jsonb, 'খ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-13', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ১৩ ও ১৪ নং প্রের উত্তর দাও : দিনমজুর ফজলু শহরে বহু পরিশ্রম করে গ্রামের স্কুলে ছেলে সাজ্জাাদকে পড়াালেখা করান। কখনো ছেলের পড়াাশোনায় যেন বিঘ্ন না ঘটে, সেজন্য বহু কে নিজের কাজ চালিয়ে যান এবং গ্রামে টাকা । পাঠান। সাজ্জাাদও বাবার স্বপ্নকে বুকে ধারণ করে দৃঢ় চিত্তে পড়াাশোনা করে এবার মেডিকেলে ভর্তি হয়। উদ্দীপকের ফজলু ''জীবন-সঙ্গীত'' কবিতার কোন পঙক্তির ভাবটি নিজের মধ্যে ধারণ করতে পেরেছেন?', 'mcq', '{"ক":"করো না সুখের আশ","খ":"বাহ্যদৃশ্যে ভুলো না রে মন","গ":"ভয়ে ভীত হইও না মানব","ঘ":"করো নিত্য নিজ কাজ"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-14', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'উদ্দীপকের সাজ্জাাদের চরিত্রে ''জীবন-সঙ্গীত’ কবিতার যে শিক্ষাটি ফুটে উঠেছে, তা হলো- i. সংগ্রামশীলতা ii. সিদ্ধাে দৃঢ়তা iii. কীর্তিমানকে অনুসরণ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
