  ('bn1-board-jessore-2019-mcq-18', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'ক্র্যাাক প্লাটুনের অন্যতম গেরিলা যোদ্ধা আজাদ মিলিটারির হাতে ধরা পড়লে তথ্য আদায়ের জন্য তার উপর অনেক অত্যাাচার করা হয়। আজাদের মা সাফিয়াা বেগম রমনা থানায় ছেলের সাথে দেখা করতে এসে অত্যাাচারের কথা জানতে পেরে ছেলেকে বলেন, “শক্ত হয়ে থেকো বাবা, কোনো কিছু স্বীকার করবে না। ” উদ্দীপকের সাফিয়াা বেগম ‘একাত্তরের দিনগুলি’ রচনার কোন চরিত্রের প্রতিরূপ?', 'mcq', '{"ক":"জাহানারা ইমাম","খ":"শরীফ","গ":"মতিয়ুুর রহমান","ঘ":"রুমী"}'::jsonb, 'ক', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-19', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', '''বহিপীর'' নাটকে ‘হঠাৎ আশাতীত কাজ'' কে করেছে?', 'mcq', '{"ক":"বহিপীর","খ":"হাশেম","গ":"তাহেরা","ঘ":"হাতেম"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
  ('bn1-board-jessore-2019-mcq-20', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', '“আপনি হ্যাঁাঁ বলেননি লজ্জাায়, আর উনি হ্যাঁাঁ বলেননি মত ছিল না বলে”- উক্তিতে হাশেম চরিত্রের কোন মনোভাব ফুটে উঠেছে?', 'mcq', '{"ক":"সহানুভূতি","খ":"যুক্তিবাদী","গ":"প্রতিবাদী","ঘ":"পরোপকারী"}'::jsonb, 'খ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
