  ('bn1-board-jessore-2019-mcq-26', 'class9-bangla-1st-bn-guide', 'যশোর বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ৬ ও ৭ নং প্রের উত্তর দাও : ২০১৮ সালের এশিয়াা কাপের প্রথম ম্যাাচে বাংলাদেশের ব্যাাটসম্যাান তামিম ইকবাল ২ রান করে কবজিতে প্রচণ্ড আঘাত পেয়ে মাঠের বাইরে চলে যান। মাঠে মুশফিক যেন একাই রুখে দাঁড়াান, বেঁঁধে মাঠে নামেন তামিম ইকবাল। এক হাতে শ্রীলঙ্কান বোলারদের বিরুে। ক্রি জের অন্য প্রাে যখন শেষ ব্যাাটসম্যাান আউট হন, তখন পুরো বিশ্বকে অবাক করে দিয়ে হাতে ব্যাােজ ব্যাাট চালিয়ে দেশের জয়ের আশা বাঁচিয়ে রাখেন। উদ্দীপকের মুশফিকের দৃঢ়তায় ''সাহসী জননী বাংলা'' কবিতার কোন পঙক্তিটি সাদৃশ্যপূণ?', 'mcq', '{"ক":"ভোজ হবে আজ প্রতিশোধে","খ":"বুকে চাপা মৃতের আগুন","গ":"কবিতার হাতে রাইফেল","ঘ":"কে দেখাল মহাপ্রতিরোধ"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-jessore-2019-mcq', false, null, 'board-mcq', null, null, 'jessore', 2019, null),
