  ('bn1-board-rajshahi-2019-mcq-06', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ২০ ও ২১ নং প্রের উত্তর দাও : (i) পৃথিবীতে সব কিছু জীণ হয়, হারিয়ে যায়, প্রাচীন সভ্যতা নিিহ্ন হয়, বিমূঢ় লোকালয় নিঃঃশেষ হয় । (ii) অপরদিকে সমুের কোনো শেষ নেই। সমুদ্র সবদাই স্বতন্ত্র এবং নিিন্ত উদ্দীপক (i) এর সঙ্গে ‘সেইদিন এই মাঠ’ কবিতার সাদৃশ্যপূণ চরণ হলো- কে সেইদিন এই মাঠ স্তব্ধ হবে নাকো জানি—', 'mcq', '{"ক":"সোনার স্বপ্নের সাধ পৃথিবীতে কবে আর ঝরে","খ":"চালতাফুল কি ভিজিবে না শিশিরের জলে","গ":"সেই দিন এই মাঠ স্তব্ধ হবে নাকো জানি-","ঘ":"এশিরিয়াা ধুলো আজ বেবিলন ছাই হয়ে আছে"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-rajshahi-2019-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2019, null),
  ('bn1-board-rajshahi-2019-mcq-07', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০১৯', 'উদ্দীপক (ii) এবং ''সেইদিন এই মাঠ'' কবিতার ভাবে প্রকাশ পায় প্রকৃতির— i. প্রাণময়তা ii. ব্যস্ততা iii. সৌন্দয নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', null, 1, false, 'bn1-board-rajshahi-2019-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2019, null),
