  ('bn1-board-rajshahi-2019-mcq-11', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ২৫ ও ২৬ নং প্রের উত্তর দাও : বাজারের এক পাশে অনেক মানুষের জমায়েত দেখে এগিয়ে যান রহমান সাহেব। দেখে একটি প্রতিবন্ধী কিশোরকে অনেকে বিরক্ত করছে। কেউ কেউ আবার মজা করছে। তিনি কিশোরটিকে বাড়িতে নিয়ে আসেন। তার বড় ছেলের রজত কিশোরটিকে ডাক্তারের কাছে নিয়ে যাওয়াার প্রস্তাব করলে রহমান সাহেব বলেন, “এত বাড়াাবাড়ির দরকার নেই।” “এদেরকে সঠিকভাবে চিকিৎসা দিলে এরা স্বাভাবিক জীবন স্রোতে ফিরে আসতে পারে।” এ কথা বলে রজত তাকে ডাক্তারের কাছে নিয়ে যায় । রহমান সাহেবের সঙ্গে ''বহিপীর'' নাটকের কোন চরিত্রের সাদৃশ্য রয়েছে?', 'mcq', '{"ক":"তাহেরা","খ":"খোদেজা","গ":"হাতেম আলি","ঘ":"হাশেম আলি"}'::jsonb, 'খ', null, 1, false, 'bn1-board-rajshahi-2019-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2019, null),
