  ('bn1-board-rajshahi-2019-mcq-25', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০১৯', 'উদ্দীপকটি পড়ে ৬ ও ৭ নং প্রের উত্তর দাও : শিল্পপতি অসিত চট্টোপাধ্যাায়ের বাড়িতে দারোয়াানের চাকরি করে বৃদ্ধ তাপস। নিচু জাতের বলে কখনো দারোয়াানকে অবজ্ঞা করেননি অসিত ও চট্টোপাধ্যাায়। ''তাপসদা'' বলেই সম্বোধন করেন। তিনি দারোয়াানকে। বয়োবৃদ্ধ তাপস এক সময়। কাজ করার সামর্থ্য হারিয়ে তার ছেলেকে নিজের স্থলে নিয়োগের জন্য প্রশিক্ষণ দিতে থাকে। কিন্তু তাপস একদিন গাড়ি ধুতে গিয়ে গাড়ির একটি গ্লাাস ভেঙে ফেলে ছেলেটি। এতে ছেলের ভবিষ্যৎ নিয়ে চিিত হয়ে পড়ে। উদ্দীপকের অসিত চট্টোপাধ্যাায় ‘অভাগীর স্বগ’ গের কোন চরিত্রের বিপরীত?', 'mcq', '{"ক":"পাঁড়ে","খ":"দারোয়াান","গ":"অধর রায়","ঘ":"ঠাকুরদাস মুখোপাধ্যাায়"}'::jsonb, 'গ', null, 1, false, 'bn1-board-rajshahi-2019-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2019, null),
