  ('bn1-board-dhaka-2019-mcq-01', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০১৯', 'উদ্দীপকের সুরুজ আলি ''কাকতাড়ুুয়াা'' উপন্যাাসের কোন চরিত্রকে মনে করিয়ে দেয়?', 'mcq', '{"ক":"আহাদ মুন্সি","খ":"কুদ্দুস","গ":"জয়নাল","ঘ":"ফজু মিয়াা"}'::jsonb, 'ক', null, 1, false, 'bn1-board-dhaka-2019-mcq', false, null, 'board-mcq', null, 'শফিক মুক্তিযোদ্ধাদেরকে বিভিন্নভাবে সাহায্য করে। একদিন রাজাকার সুরুজ আলি শফিককে ধরে পাকসেনাদের ক্যাাে নিয়ে যায়। কিন্তু শফিক মৃত্যুভয়ে মোটেই ভীত হয় না।', 'dhaka', 2019, null),
  ('bn1-board-dhaka-2019-mcq-02', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০১৯', 'উদ্দীপকের শফিক ও ''কাকতাড়ুুয়াা'' উপন্যাাসের বুধার মধ্যে প্রকাশ পেয়েছে— i. দেশাত্মবোধ ii. সাহসিকতা iii. প্রতিশোধস্পৃহা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-dhaka-2019-mcq', false, null, 'board-mcq', null, 'শফিক মুক্তিযোদ্ধাদেরকে বিভিন্নভাবে সাহায্য করে। একদিন রাজাকার সুরুজ আলি শফিককে ধরে পাকসেনাদের ক্যাাে নিয়ে যায়। কিন্তু শফিক মৃত্যুভয়ে মোটেই ভীত হয় না।', 'dhaka', 2019, null),
  ('bn1-board-dhaka-2019-mcq-03', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০১৯', 'সমরের কথায় ''পিজননী'' কবিতায় খোকার কোনটি প্রকাশ পেয়েছে?', 'mcq', '{"ক":"স্নেহের আকুলতা","খ":"বেয়াাড়াাপনা","গ":"অন্যাায় আবদার","ঘ":"মাতৃভক্তি"}'::jsonb, 'গ', null, 1, false, 'bn1-board-dhaka-2019-mcq', false, null, 'board-mcq', null, 'ক্যাান্সারে আক্রান্ত সমরের অবস্থা ভালো না। ডাক্তার বলেছেন, সমর আর বেশিদিন বাঁচবে না। সমর মাকে বলে ভালো হয়ে খেলতে গেলে মা যেন নিষেধ না করেন। এ কথা শুনে মায়ের চোখে শুধুই অশ্রু।', 'dhaka', 2019, null),
