  ('bn1-board-dhaka-2019-mcq-21', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০১৯', '‘জীবন-সঙ্গীত'' কবিতায় কবি মানবজীবনকে বৃথা বলতে চাননি। কারণ— i. মানবজীবন সাফল্যে পরিপূণ ii. মানজীবন তাৎপযময় iii. মানুষের অনেক দায়িত্ব রয়েছে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', null, 1, false, 'bn1-board-dhaka-2019-mcq', false, null, 'board-mcq', null, null, 'dhaka', 2019, null),
