  ('bn1-board-mymensingh-2020-mcq-07', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'হে মোর দুর্ভাগা দেশ! যাদের করেছ অপমান অপমানে হতে হবে তাহাদের সবার সমান- এখানে কাদের কথা বলা হয়েছে?', 'mcq', '{"ক":"নেতাদের","খ":"ভদ্র সম্প্রদায়ের","গ":"শ্রমজীবী মানুষের","ঘ":"মনীষীদের"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
