  ('bn1-board-mymensingh-2020-mcq-09', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'মানুষ লোভের ফাঁদে ধরা দিতে ভয় পায় কেন?', 'mcq', '{"ক":"মনুষ্যত্বের কারণে","খ":"মানুষের ভয়ে","গ":"জীবসত্তার জন্যে","ঘ":"মৃত্যুর জন্যে"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-10', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'পিঁঁড়েয় বসে পেঁঁড়োর খবর- এটা কী?', 'mcq', '{"ক":"খনার বচন","খ":"ডাক","গ":"প্রবাদ বাক্য","ঘ":"উপকথা"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
