  ('bn1-board-mymensingh-2020-mcq-12', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'সিনথিয়াার বাগানে বেশ কটা হাই-িড টি রোজের গাছ আছে। মাখনের মতো রঙের ''পিস'', কালচে- মেরুর ''বনি িন্স''। সিনথিয়াার বাগানের সাথে মিল রয়েছে কার বাগানের?', 'mcq', '{"ক":"ঠাকুরদাস মুখুয্যের","খ":"অধর রায়ের","গ":"বাণীকন্ঠের","ঘ":"জাহানারা ইমামের"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
