  ('bn1-board-mymensingh-2020-mcq-15', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উদ্দীপকটি পড়ে ১ ও ২ নং প্রের উত্তর দাও : স্বাধীনতা ভীষণ আনের। স্বাধীনতা খুব দরকার। উদ্দীপকের স্বাধীনতা শের অথ-', 'mcq', '{"ক":"মুক্তির স্বাদ পাওয়াা","খ":"ইচ্ছামতো চলাফেরা করা","গ":"মন যা চায় তাই করা","ঘ":"সবার উপরে নেতৃত্ব দেওয়াা"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-16', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উদ্দীপকের সাথে কার অনুভূতির মিল রয়েছে?', 'mcq', '{"ক":"মধুর","খ":"শাহাবুদ্দিনের","গ":"বুধার","ঘ":"মিঠুর"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-17', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'আবার আসিব ফিরে ধানসিঁঁড়িটির তীরে হয়তো মানুষ নয় হয়তো শঙ্খচিল শালিকের বেশে হয়তো ভোরের কাক হয়ে এই কার্তিকের নবাের দেশে। উদ্দীপকটির সাথে নিচের কোন কবিতার মিল পাওয়াা যায়?', 'mcq', '{"ক":"বঙ্গবাণী","খ":"আমি কোনো আগন্তুক নই","গ":"কপোতাক্ষ নদ","ঘ":"সেইদিন এই মাঠ"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-18', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'ক্ষুধার রাজ্যে পৃথিবী গদ্যময় পূর্ণিমার চাঁদ যেন ঝলসানো রুটি কবিতা তোমায় আজকে দিলাম ছুটি। উদ্দীপকটির মিল পাওয়াা যায় নিচের কোন পক্তির সাথে?', 'mcq', '{"ক":"করো না মানবগণ, বৃথা ক্ষয় এ জীবন","খ":"কত কথা আজ মনে পড়ে তার, গরীবের ঘর তার","গ":"ঘরেতে অভাব; পৃথিবীটা তাই মনে হয় কালো ধোঁঁয়াা","ঘ":"অ আ ক খ বর্ণমালা পথে পথে তেপান্তরে ঘো"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-19', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'পলি ভাবীর চোখের সামনে মুক্তিযুের সময় পাক সেনারা তার স্বামী, শ্বশুর ও সন্তানকে হত্যাা করে। পলি ভাবী প্রতিশোধ নেওয়াার জন্য মাইন সংগ্রহ করে। বুকে মাইন বেঁঁধে পাক সেনাদের গাড়ির উপর ঝাঁপিয়ে পড়ে এবং অনেক পাক হানাদারকে হত্যাা করে। উদ্দীপকে ‘কাকতাড়ুুয়াা'' উপন্যাাসের কোন চরিত্রের সাদৃশ্য আছে?', 'mcq', '{"ক":"বুধা","খ":"কুন্তি","গ":"কুদ্দুস","ঘ":"আহাদ মুন্সি"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-20', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'তুমি রাজনীতির কবি তুমি বাংলার জন্য দিয়েছ সবই তুমি স্বাধীনতার ঘোষক তুমি বাঙালি জাতির পথপ্রদশক উদ্দীপকে ''স্বাধীনতা, এ শব্দটি কীভাবে আমাদের হলো'' কবিতার কোন দিককে নির্দেশ করে? i. স্বাধীনতার ডাক ii. আত্মত্যাাগের কথা iii. বাঙালি জাতিকে প্রেরণাদানের কথা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-21', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উত্তম কথা, কেন বলছেন পীর সাহেব উক্তিটি কার?', 'mcq', '{"ক":"হাতেম আলির","খ":"খোদেজার","গ":"হাশেমের","ঘ":"তাহেরার"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-22', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উদ্দীপকটি পড়ে ৮ ও ৯ নং প্রের উত্তর দাও : লিমা আট বছর বয়সে মাকে হারায়। মাকে হারিয়ে সে তার জীবনের সকল স্নেহ-মমতা, ভালোবাসা থেকে বঞ্চিত হয়। উদ্দীপকের লিমার সাথে সাদৃশ্য রয়েছে কোন চরিত্রের?', 'mcq', '{"ক":"খোদেজা","খ":"অভাগী","গ":"তাহেরা","ঘ":"সর্বজয়াা"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-23', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উদ্দীপকের চরিত্রটি- i. নারী আন্দো লনের প্রতীক ii. নারীর অসহায়ত্বের প্রতীক iii. নারী জাগরণের প্রতীক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-24', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'বাহিরেতে নাচে জোনাকি আলোয় থমথম কাল রাত- কী অথ প্রকাশ করে?', 'mcq', '{"ক":"নীরব প্রকৃতি","খ":"দুঃখের অশনি সংকেত","গ":"জোনাকির মিটি মিটি আলো","ঘ":"ঘোর আন্ধার"}'::jsonb, 'খ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-25', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'ভারতে এক মহিলার মুরগির ঘরে সন্ধ্যাায় ছোট এক চিতাবাঘ ঢুকে পড়ে। মুরগিদের হৈচৈ শুনে মহিলা টচলাইট ঘরে ধরলে বাঘের দুটি চোখ লাইটের আলোয় জ্বলজ্বল করে ওঠে। কিছু বোঝার আগেই চিতাবাঘ এক লাফে মহিলার ঘাড়ের ওপর লাফিয়ে পড়ে। পাশেই ছিল মহিলার পোষা কুকুর। সে দ্রুত বাঘকে ধরে ফেলে এবং ঘাড় মটকিয়ে বাঘকে হত্যাা করে। উদ্দীপকের পোষা কুকুর ''নিয়তি'' গের যে চরিত্রের প্রতিনিধি তা হলো-', 'mcq', '{"ক":"বেঙ্গল টাইগার","খ":"নেকড়ে বাঘ","গ":"তক্ষক","ঘ":"কেউটে সাপ"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-26', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'প্রতিবেশীর আঁধার ঘরে জ্বালতে পারে আলো- কারা আলো জ্বালতে পারে?', 'mcq', '{"ক":"ধনীরা","খ":"শিক্ষিতরা","গ":"আত্মীয়রা","ঘ":"দরিদ্র মানুষেরা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
