  ('bn1-board-mymensingh-2020-mcq-28', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'শালিক শুক বুলায় মুখ— কোথায়?', 'mcq', '{"ক":"নদীল জলে","খ":"থল-ঝাঁঝিতে","গ":"পুকুরের জলে","ঘ":"বরফের স্তূপে"}'::jsonb, 'খ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
  ('bn1-board-mymensingh-2020-mcq-29', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২০', 'উপন্যাাসের প্রধান উপজীব্য হলো প্লট। ঐ প্লট বা আখ্যাানভাগ তৈরি হয়ে ওঠে গল্প ও তার ভেতরে উপিত বিভিন্ন চরিত্রের সমন্বয়ে। ফলে উপন্যাাস মানুষের কাছে জনিয় হয়ে ওঠে। কারণ উপন্যাাস— i. সহজ-সরল প্রাঞ্জল ii. পাঠক নিজেকে খুঁজে পায় iii. সমাজের বাস্তব চিত্র ফুটে ওঠে। নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-all-2020-mcq', false, null, 'board-mcq', null, null, 'all', 2020, null),
