  ('bn1-board-dinajpur-2020-mcq-01', 'class9-bangla-1st-bn-guide', 'দিনাজপুর বোর্ড ২০২০', 'নামাজের ঘরে মোমবাতি মানে, দরগায় মানে দান- চরণটিতে পিজননীর কোন দিকটির ইঙ্গিত রয়েছে? i. প্রচলিত কুসংস্কার ii. ধর্মীয় রীতি iii. সন্তানের সুস্থতার আকুতি নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'bn1-board-dinajpur-2020-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2020, null),
