  ('bn1-board-dinajpur-2020-mcq-07', 'class9-bangla-1st-bn-guide', 'দিনাজপুর বোর্ড ২০২০', 'মনি, শিমু, রিদম, রাফী, সৌম্য, অথৈ একই গ্রামে একসাথে বেড়ে উঠেছে। সেদিন শিমু হঠাৎ জানাল সপরিবারে ওদের বিদেশে যাওয়াা পাকাপাকি। সবার মন খারাপ। শিমু আবেগাপ্লুত হয়ে রাফীকে বলল, “সাবধানে থেকো, তোমার তো আবার রাগ আর জেদ বেশি”— উদ্দীপকের শিমু ''কাকতাড়ুুয়াা উপন্যাাসের যার প্রতিনিধিত্ব করে-', 'mcq', '{"ক":"কুন্তি","খ":"মধু","গ":"রানি","ঘ":"ফুলকলি"}'::jsonb, 'গ', null, 1, false, 'bn1-board-dinajpur-2020-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2020, null),
  ('bn1-board-dinajpur-2020-mcq-08', 'class9-bangla-1st-bn-guide', 'দিনাজপুর বোর্ড ২০২০', 'শত বৎসর ধরে প্রাণপণে চেষ্টা সত্ত্বেও আমাদের জনশক্তিকে উদ্বুদ্ধ করতে ব্যথ হওয়াার কারণ কী?', 'mcq', '{"ক":"অভিজাত শ্রেণির কথা না শোনা","খ":"ছোটলোকদের প্রতি উদার মনোভাব","গ":"ধর্মীয় গোঁঁড়াামি ও অশিক্ষা","ঘ":"ভাগ্যের নির্ম পরিহাস"}'::jsonb, 'খ', null, 1, false, 'bn1-board-dinajpur-2020-mcq', false, null, 'board-mcq', null, null, 'dinajpur', 2020, null),
