  ('bn1-board-barishal-2020-mcq-19', 'class9-bangla-1st-bn-guide', 'বরিশাল বোর্ড ২০২০', 'উদ্দীপকটি পড়ে ৫ ও ৬ নং প্রের উত্তর দাও : পিতৃ-মাতৃহীন মিতুকে তার চাচি গ্রামের। প্রভাবশালী ব্যক্তি বুড়ো মকবুল মিয়াার সাথে বিয়ে দিতে চায়। মিতু পালিয়ে গিয়ে পাশের গ্রামের আশ্রয় নেয়। এতে উভয় পক্ষের হুমকি ও পাল্টাা হুমকিতে পরিিতি ভয়ংংকর হয়ে ওঠে। অবশেষে মকবুল মিয়াা বাস্তব অবস্থা অনুধাবন করে সবকিছু সমাজহিতৈষী ব্যক্তি সগীর সাহেবের বাড়িতে মেনে নেয়। উদ্দীপকের মিতু ''বহিপীর'' নাটকের তাহেরার সাথে কোন বৈশিে সাদৃশ্যপূণ?', 'mcq', '{"ক":"মা-বাবা হারা হওয়াা","খ":"চাচির ঘরে আশ্রয় গ্রহণ","গ":"বাল্যবিবাহের শিকার","ঘ":"পালিয়ে যাওয়াা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-barishal-2020-mcq', false, null, 'board-mcq', null, null, 'barishal', 2020, null),
