  ('bn1-board-chattogram-2020-mcq-04', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২০', 'উদ্দীপকে ‘তোমাকে পাওয়াার জন্যে, হে স্বাধীনতা’ কবিতার যে বিষয়/বিষয়গুলো প্রকাশ পেয়েছে- i. স্বাধীনতার জন্য সাধারণ মানুষের আত্মত্যাাগ ii. পাকিস্তানি সেনাদের ববরোচিত আচরণ iii. মুক্তিযোদ্ধাদের সংগ্রামী ভূমিকার প্রতি সহমর্মিতা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2020-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2020, null),
