  ('bn1-board-dhaka-2020-mcq-01', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০২০', 'উদ্দীপকের মায়ের অনুভূতি ''পিজননী'' কবিতার কোন চরণে প্রকাশ পেয়েছে?', 'mcq', '{"ক":"উত্তর দিতে দুখিনী মায়ের দ্বিগুণ বাড়িত জ্বালা","খ":"কহিতে কহিতে মুখখানি ভাসে বহিয়াা নয়ন নীর","গ":"সাঁঝ হয়ে গেল তবু আসে নাকো, আই ঢাই মার প্রাণ","ঘ":"আঁধারের সাথে যুঝিয়াা তাহার ফুরায়ে এসেছে তেল"}'::jsonb, 'গ', null, 1, false, 'bn1-board-dhaka-2020-mcq', false, null, 'board-mcq', null, 'রাজিব শহরে পড়ে। মা তাকে পড়াালেখার খরচ পাঠাতে পারে না। টিউশনির কারণে এবারের ঈদে সে বাড়িতে আসতে না পারায় মা খাবার সামনে নিয়ে চোখের পানি ফেলছে।', 'dhaka', 2020, null),
  ('bn1-board-dhaka-2020-mcq-02', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০২০', 'উদ্দীপক ও ''পিজননী'' কবিতার মূল সুর যে দিক থেকে একই সূত্রে গাথা তা হলো-- i. সন্তানবাৎসল্যতা ii. কতব্যপরায়ণতা', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'bn1-board-dhaka-2020-mcq', false, null, 'board-mcq', null, 'রাজিব শহরে পড়ে। মা তাকে পড়াালেখার খরচ পাঠাতে পারে না। টিউশনির কারণে এবারের ঈদে সে বাড়িতে আসতে না পারায় মা খাবার সামনে নিয়ে চোখের পানি ফেলছে।', 'dhaka', 2020, null),
  ('bn1-board-dhaka-2020-mcq-03', 'class9-bangla-1st-bn-guide', 'ঢাকা বোর্ড ২০২০', 'উদ্দীপকের অনিকের অবস্থা ''প্রবাস বন্ধু'' রচনার। কোন উক্তিতে স্পষ্ট ফুটে উঠেছে?', 'mcq', '{"ক":"আমার ভৃত্য আগা আবদুর রহমান এককালে মেসের চার্জে ছিলেন","খ":"তোমার বন্ধুটার সঙ্গে আমার তনুটা মিলিয়ে দেখো দিকিনি","গ":"তাড়াাতাড়ি এগিয়ে অভয়বাণী দিল— রান্নাঘরে আরো আছে","ঘ":"মাথা নিচু করে বলল, ''আমার রান্না হুজুরের পছন্দ হয়নি''"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-dhaka-2020-mcq', false, null, 'board-mcq', null, 'বিশ্ববিদ্যাালয়ে পড়াার জন্য ঢাকায় মামার বাসায় থাকে মাতৃহীন অনিক। নিঃঃসন্তান মামির অকারণে ঘর গোছানো, লেখাপড়াার খোঁঁজ-খবর নেওয়াা মাঝে মাঝে তার কাছে অত্যাাচারের মতো মনে হয়। বিশেষ করে খাওয়াা-দাওয়াার ব্যাাপারে সে কিছুতেই মামিকে খুশি করতে পারে না।', 'dhaka', 2020, null),
