  ('bn1-board-chattogram-2023-mcq-09', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৩', 'নিচের উদ্দীপকটি পড় এবং ২৯ নং প্রের উত্তর দাও : বড় ভাই সজীব ছোট ভাই রাকিবকে মেরে বাড়ি থেকে তাড়িয়ে দেয়। এতে ক্ষিপ্ত না হয়ে বরং রাকিব বলেন, হে আল্লাহ! তুমি আমার ভাইকে সঠিক বুঝ দান কর। উদ্দীপকের ঘটনা মহানবি (স.)-এর জীবনের কোন ঘটনার সাথে সংগতিপূণ?', 'mcq', '{"ক":"মদীনাবাসীর অত্যাাচার","খ":"তায়েফবাসীর অত্যাাচার","গ":"কুরাইশদের অত্যাাচার","ঘ":"মক্কাাবাসীর অত্যাাচার"}'::jsonb, 'খ', null, 1, false, 'bn1-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
  ('bn1-board-chattogram-2023-mcq-10', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৩', 'নিচের উদ্দীপকটি পড় এবং ৩০ নং প্রের উত্তর দাও : বড় ভাই সজীব ছোট ভাই রাকিবকে মেরে বাড়ি থেকে তাড়িয়ে দেয়। এতে ক্ষিপ্ত না হয়ে বরং রাকিব বলেন, হে আল্লাহ! তুমি আমার ভাইকে সঠিক বুঝ দান কর। রাকিবের মধ্যে মহানবি (স.)-এর চরিত্রের যে বৈশিষ্ট্য লক্ষ করা যায়— i. মহানুভবতা ii. উদারতা iii. সহিষ্ণুুতা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2023-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2023, null),
