  ('bn1-board-mymensingh-2023-mcq-01', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২৩', 'নিচের উদ্দীপকটি পড়ে ২১ নং প্রের উত্তর দাও : বুলবুল সাহেব এম.এ. পাস করে সরকারি চাকুরি পেয়েছেন। তাঁর দৃিতে ন্যাায়-অন্যাায় বড়ো কথা নয়; অথ উপাজনই মূল লক্ষ্য। উক্ত ভাবসত্য নিচের কোন উক্তিতে প্রকাশ পেয়েছে?', 'mcq', '{"ক":"অর্থ নিগড়ে বন্দী","খ":"সরকারি চাকুরিতে বিভোর","গ":"প্রাণিত্বের বাঁধনে বন্দি","ঘ":"মনুষ্যত্বের গুণে বলিয়াান"}'::jsonb, 'ক', null, 1, false, 'bn1-board-all-2023-mcq', false, null, 'board-mcq', null, null, 'all', 2023, null),
