  ('bn1-board-mymensingh-2023-mcq-06', 'class9-bangla-1st-bn-guide', 'ময়মনসিংংহ বোর্ড ২০২৩', 'নিচের উদ্দীপকটি পড় এবং ২৬ ও ২৭ নং প্রের উত্তর দাও : মাদার তেরেসা জীবনের সবস্ব দিয়ে মানুষের সেবা করেছেন। এমনকি নোবেল পুরস্কারের অথও মানুষের সেবায় উৎসগ করেছেন। তাঁর এই অবদানের জন্য সমগ্র পৃথিবী তাঁকে একনামে চিনে। উদ্দীপকের মাদার তেরেসা ''রানার'' কবিতার কোন চরিত্রের প্রতিনিধি?', 'mcq', '{"ক":"কবি সুকান্ত ভট্টাচার্য","খ":"রানারের প্রিয়াা","গ":"রানার","ঘ":"রাতের তারা"}'::jsonb, 'গ', null, 1, false, 'bn1-board-all-2023-mcq', false, null, 'board-mcq', null, null, 'all', 2023, null),
