  ('bn1-board-cumilla-2023-mcq-04', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০২৩', 'নিচের উদ্দীপকটি পড়ে ২৯ ও ৩০ নং প্রের উত্তর দাও : “হত্যাার উৎসব ভেবে পার্কে মাঠে ক্যাাম্পাসে বাজারে বিষাক্ত গ্যাাসের মতো মৃত্যুর বীভৎস গন্ধ দিয়েছে ছড়াে আমি তো তাদের জন্য অমন সহজ মৃত্যু করি না কামনা ।উদ্দীপকের ভাবনা “কাকতাড়ুুয়াা'' উপন্যাাসের কোন বাক্যে প্রতিধ্বনিত হয়েছে?', 'mcq', '{"ক":"লোকে জানুক আমি স্বাধীনতা যুদ্ধে শহিদ হয়েছি।","খ":"আধা-পোড়াা বাজারটার দিকে তাকিয়ে ওর চোখ লাগ হতে থাকে।","গ":"রাতের বেলা ওরা বাজারে ভয়ে হাইবাজি দেখবে।","ঘ":"সবার উচিত গীরে থেকে লড়াাই করা।"}'::jsonb, 'খ', null, 1, false, 'bn1-board-cumilla-2023-mcq', false, null, 'board-mcq', null, null, 'cumilla', 2023, null),
