  ('bn1-board-cumilla-2024-mcq-27', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০২৪', 'উদ্দীপকের রজত সাহেবের সাথে ''বহিপীর'' নাটকের কোন চরিত্রের সাদৃশ্য রয়েছে?', 'mcq', '{"ক":"তাহেরা","খ":"বহিপীর","গ":"খোদেজা","ঘ":"হাতেম আলি"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-cumilla-2024-mcq', false, null, 'board-mcq', null, 'রজত সাহেব সামান্য বেতনের কমচারী। তার ছেলে বুয়েটে পড়ার সুযোগ পেলেও খরচের কথা ভেবে তিনি দুিন্তাগ্রস্থ হয়ে পড়েন। এ কথা জেনে এক ঠিকাদার রজত সাহেবকে অর্থের বিনিময়ে অন্যাায় প্রস্তাব দিলেও তিনি রাজি হননি।', 'cumilla', 2024, null),
  ('bn1-board-cumilla-2024-mcq-28', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০২৪', 'উদ্দীপকের মূলভাবের মধ্যে ''বহিপীর'' নাটকের কোন দিকটি ফুটে উঠেছে?', 'mcq', '{"ক":"নৈতিকতা","খ":"মনোবেদনা","গ":"স্বার্থপরতা","ঘ":"দুঃখকথা"}'::jsonb, 'ক', null, 1, false, 'bn1-board-cumilla-2024-mcq', false, null, 'board-mcq', null, 'রজত সাহেব সামান্য বেতনের কমচারী। তার ছেলে বুয়েটে পড়ার সুযোগ পেলেও খরচের কথা ভেবে তিনি দুিন্তাগ্রস্থ হয়ে পড়েন। এ কথা জেনে এক ঠিকাদার রজত সাহেবকে অর্থের বিনিময়ে অন্যাায় প্রস্তাব দিলেও তিনি রাজি হননি।', 'cumilla', 2024, null),
  ('bn1-board-cumilla-2024-mcq-29', 'class9-bangla-1st-bn-guide', 'কুমিল্লা বোর্ড ২০২৪', '''জীবন সঙ্গীত ''কবিতা অনুসারে উদ্দীপকের সুমিতের বক্তব্যে ফুটে উঠেছে- i. বৈরাগ্য ii. আধ্যাাত্মিকতা iii. হতাশা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'bn1-board-cumilla-2024-mcq', false, null, 'board-mcq', null, 'ধনী হওয়া সত্ত্বেও শিহাব কঠোর পরিশ্রম করেন। তা দেখে বন্ধু সুমিত তাঁকে বলেন-দু''দিনের পৃথিবী এত পরিশ্রম করে কী লাভ? উত্তরে শিহাব বলেন, "পৃথিবী হচ্ছে বিশাল কমক্ষেত্র।"', 'cumilla', 2024, null),
