  ('bn1-board-chattogram-2024-mcq-21', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'শুধালো সেজন, "সাগর হইতে কে অধিক ধনবানন জ্ঞানী বলে, "বাছা, তুষ্ট হৃদয় তারো চেয়ে গরীয়া চরণ দুটির ভাবের সাথে তোমার পাঠ্য কোন কবি ভাবের মিল আছে?', 'mcq', '{"ক":"জীবন-সঙ্গীত","খ":"রানার","গ":"আশা","ঘ":"পল্লিজননী"}'::jsonb, 'গ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-22', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', '''নিমগাছ'' কোন ধরনের গল্প?', 'mcq', '{"ক":"রম্য গল্প","খ":"অনুগল্প","গ":"জীবনমুখী গল্প","ঘ":"প্রতীকী গল্প"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-23', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'চোখ লাল হলে বুধার ভিতর কী জাগে?', 'mcq', '{"ক":"কান্নার আবেগ","খ":"অতীত স্মৃতি","গ":"কিছু করার ইচ্ছা","ঘ":"তীব্র ঘৃণাবোধ"}'::jsonb, 'গ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-24', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', '"সেসব কাহার জন্ম নিণয় ন জানি"-কবি আবদুল হাকিম কাদের সম্পর্কে এ উক্তিটি করেছেন?', 'mcq', '{"ক":"দেশি ভাষার প্রতি যাদের অনুরাগ নেই।","খ":"বাংলায় জন্মগ্রহণ করে যারা বাংলা ভাষাকে ঘৃণা করে।","গ":"দেশি ভাষায় বিদ্যাা লাভ করে যারা তৃপ্ত নয়।","ঘ":"নিজ দেশ ত্যাাগ করে যারা বিদেশে যায়।"}'::jsonb, 'খ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, null, 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-25', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'কবিতাংশের ভাব ''শিক্ষা ও মনুষ্যত্ব'' প্রবের যেদিকটি তুলে ধরে তা হলো-', 'mcq', '{"ক":"লেফাফা দুরস্তি","খ":"প্রাণিত্বের বাঁধন থেকে মুক্তি","গ":"জীবসত্তার ঘরের বিশৃঙ্খলা","ঘ":"অর্থচিন্তার নিগড়ে সবার বন্দিদশা"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '"নিধন কামনা করে, শত মুদ্রা হয় তার সহস্র পাইতে আশা, একশত আছে যার। পাইলে হাজার, ইচ্ছা লক্ষপতি হইবার, শতলক্ষ পায় সাধ, লক্ষপতি যিনি তার।"', 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-26', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'উক্ত দিক আমাদেরকে- i. জীবসত্তার ঘরে আবদ্ধ রাখে ii. মূল্যবোধের জাগরণ ঘটায় iii. মুক্তির স্বাদ বঞ্চিত করে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '"নিধন কামনা করে, শত মুদ্রা হয় তার সহস্র পাইতে আশা, একশত আছে যার। পাইলে হাজার, ইচ্ছা লক্ষপতি হইবার, শতলক্ষ পায় সাধ, লক্ষপতি যিনি তার।"', 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-27', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'কবিতাংশটি ''মানুষ'' কবিতার কোন ভাবের সাথে সাদৃশ্যপূণ?', 'mcq', '{"ক":"সামাজিক দায়বদ্ধতা","খ":"প্রতিবাদী চেতনা","গ":"মানুষের শ্রেষ্ঠত্ব","ঘ":"স্রষ্টার মাহাত্ম্য"}'::jsonb, 'গ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '"তোমাতে রয়েছে সকল কেতাব সকল কালের জ্ঞান, সকল শাস্ত্র খুঁজে পাবে সখা খুলে দেখ নিজ প্রাণ, তোমাতে রয়েছে সকল ধম, সকল যুগাবতার, তোমার হৃদয় বিশ্ব-দেউল সকলের দেবতার।"', 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-28', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'উক্ত ভাব নিচের কোন চরণে প্রকাশ পেয়েছে?', 'mcq', '{"ক":"মানুষের চেয়ে বড় কিছু নাই, নহে কিছু মহীয়ান।","খ":"সব দেশে সব কালে ঘরে-ঘরে তিনি মানুষের জ্ঞাতি।","গ":"সব দ্বার এর খোলা রবে, চালা হাতুড়ি শাবল চালা।","ঘ":"তোমার মিনারে চড়িয়া ভণ্ড গাহে স্বার্থের জয়।"}'::jsonb, 'ক', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '"তোমাতে রয়েছে সকল কেতাব সকল কালের জ্ঞান, সকল শাস্ত্র খুঁজে পাবে সখা খুলে দেখ নিজ প্রাণ, তোমাতে রয়েছে সকল ধম, সকল যুগাবতার, তোমার হৃদয় বিশ্ব-দেউল সকলের দেবতার।"', 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-29', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'উদ্দীপকে তকরত্নের আচরণে ''অভাগীর স্বগ'' গের কোন দিকটি ফুটে উঠেছে?', 'mcq', '{"ক":"সামন্তবাদ","খ":"জাতিভেদ","গ":"নিপীড়ন","ঘ":"পণপ্রথা"}'::jsonb, 'খ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '''মহেশ'' গে গফুর ব্রাহ্মণ তকরত্নের পায়ের কাছে বসিয়া কাহন-দুই খড় ধার চাহিতে গেলে তকরত্ন তীরবৎ পিছাইয়া গিয়া কহিলেন, "আ মর, ছুয়ে ফেলবি না কি?"', 'chattogram', 2024, null),
  ('bn1-board-chattogram-2024-mcq-30', 'class9-bangla-1st-bn-guide', 'চট্টগ্রাম বোর্ড ২০২৪', 'উক্ত দিকটি প্রকাশ পেয়েছে যে বাক্যে- i. মুখে একটু নুড়ো জ্বেলে দিয়ে নদীর চড়ায় মাটি দেগে ii. সব ব্যাাটারাই এখন বামুন-কায়েত হতে চায়। iii. দুলের মড়ার কাঠ কী হবে শুনি?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-chattogram-2024-mcq', false, null, 'board-mcq', null, '''মহেশ'' গে গফুর ব্রাহ্মণ তকরত্নের পায়ের কাছে বসিয়া কাহন-দুই খড় ধার চাহিতে গেলে তকরত্ন তীরবৎ পিছাইয়া গিয়া কহিলেন, "আ মর, ছুয়ে ফেলবি না কি?"', 'chattogram', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-01', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', 'উদ্দীপকের চেতনায় বিশ্বাসী ''বহিপীর'' নাটকের কোন চরিত্র?', 'mcq', '{"ক":"তাহেরা","খ":"বহিপীর","গ":"খোদেজা","ঘ":"হাতেম আলি"}'::jsonb, 'গ', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, '"গাছ-গাছালি শেকড়-বাকলসুদ্ধ সবাই গেলে, বাপরে বলে পালায় ব্যাামো ছায়ার ওষুধ খেলে।"', 'rajshahi', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-02', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', 'উক্ত সাদৃশ্যপূণ চরিত্রে প্রকাশ পেয়েছে- i. কুসংস্কারাচ্ছন্নতা ii. ধমভীরুতা iii. অনুশোচনা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, '"গাছ-গাছালি শেকড়-বাকলসুদ্ধ সবাই গেলে, বাপরে বলে পালায় ব্যাামো ছায়ার ওষুধ খেলে।"', 'rajshahi', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-03', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', 'উদ্দীপকের ভাবার্থে ''রানার'' কবিতার রানারের কোন দিকটি গুরুত্ব পেয়েছে?', 'mcq', '{"ক":"গতিশীলতা","খ":"সেবাপরায়ণতা","গ":"নির্ভীকতা","ঘ":"কর্তব্যপরায়ণতা"}'::jsonb, 'ক', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, '"আঠারো বছর বয়স যে দুর্বার পথে প্রান্তরে ছোটায় বহু তুফান।"', 'rajshahi', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-04', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', 'উক্ত গুরুত্বপূণ দিক প্রকাশ পেয়েছে যে চরণে- i. কাজ নিয়েছে সে নতুন খবর আনার। ii. কেমন করে এ রানার সবেগে হরিণের মতো যায়। iii. আরো জোরে, আরো জোরে, এ রানার দুর্বার দুজয়। নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, '"আঠারো বছর বয়স যে দুর্বার পথে প্রান্তরে ছোটায় বহু তুফান।"', 'rajshahi', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-05', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', '''তায়েফ'' সৌদি আরবের কোন অঞ্চলের উবর প্রদেশ?', 'mcq', '{"ক":"পূর্ব","খ":"পশ্চিম","গ":"উত্তর","ঘ":"দক্ষিণ"}'::jsonb, 'ঘ', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
  ('bn1-board-rajshahi-2024-mcq-06', 'class9-bangla-1st-bn-guide', 'রাজশাহী বোর্ড ২০২৪', 'সাহিত্যের কোন শাখা সর্বাধিক পঠিত?', 'mcq', '{"ক":"নাটক","খ":"উপন্যাাস","গ":"কবিতা","ঘ":"ছোটগল্প"}'::jsonb, 'খ', null, 1, false, 'bn1-board-rajshahi-2024-mcq', false, null, 'board-mcq', null, null, 'rajshahi', 2024, null),
